def format_filter_width(width_hz):
    if width_hz < 1000:
        return f"{width_hz:.0f} Hz"
    return f"{width_hz / 1000:.1f} k"


def filter_preset_index(width_hz):
    for index, (_name, preset_width_hz) in enumerate(FILTER_WIDTH_PRESETS):
        if abs(preset_width_hz - width_hz) <= FILTER_SNAP_HZ / 2:
            return index
    return None


def next_filter_preset(width_hz):
    index = filter_preset_index(width_hz)
    return FILTER_WIDTH_PRESETS[0] if index is None else FILTER_WIDTH_PRESETS[(index + 1) % len(FILTER_WIDTH_PRESETS)]


def fine_filter_width(width_hz, delta):
    return clamp(width_hz + delta * FILTER_FINE_WIDTH_STEP_HZ, FILTER_SNAP_HZ, FILTER_LIMIT_HZ)


def symmetric_filter_bounds(low_cut, high_cut, width_hz):
    half_width = width_hz / 2.0
    center = clamp(
        (low_cut + high_cut) / 2.0,
        -FILTER_LIMIT_HZ + half_width,
        FILTER_LIMIT_HZ - half_width,
    )
    return center - half_width, center + half_width


def format_filter_cut(cut_hz):
    sign = "+" if cut_hz >= 0 else "-"
    return f"{sign}{abs(cut_hz) / 1000:.2f}k"


def filter_x(cut_hz, x0, x1, limit_hz=FILTER_LIMIT_HZ, center_hz=0.0):
    return x0 + (cut_hz - center_hz + limit_hz) / (2 * limit_hz) * (x1 - x0)


def filter_cut_at_x(x, x0, x1, limit_hz=FILTER_LIMIT_HZ, center_hz=0.0):
    fraction = clamp((x - x0) / max(1.0, x1 - x0), 0.0, 1.0)
    return int(round((center_hz + (fraction * 2.0 - 1.0) * limit_hz) / FILTER_SNAP_HZ) * FILTER_SNAP_HZ)


def filter_edit_limit(low_cut, high_cut):
    # Scale the editor around the selected RF center (0 Hz).
    outer_cut = max(abs(low_cut), abs(high_cut), 500.0)
    return int(clamp(math.ceil(outer_cut * 1.25 / 500) * 500, 1500, FILTER_LIMIT_HZ))


def draw_filter_overlay(text_cache, span_khz, low_cut, high_cut, y0, y1, alpha=1.0, tuned_offset_hz=0.0):
    if alpha <= 0.01:
        return
    canvas_w = rf_canvas_width()
    hz_per_px = max(1.0, span_khz * 1000.0 / canvas_w)
    center_x = canvas_w / 2 + tuned_offset_hz / hz_per_px
    low_x = center_x + low_cut / hz_per_px
    high_x = center_x + high_cut / hz_per_px
    raw_left = min(low_x, high_x)
    raw_right = max(low_x, high_x)
    left = clamp(raw_left, 0.0, float(canvas_w))
    right = clamp(raw_right, 0.0, float(canvas_w))
    if right <= left:
        return
    # Cool cyan keeps the passband distinct without warming the waterfall.
    # The earlier grey one-pixel edges became indistinguishable from strong
    # waterfall detail, especially at high zoom where one or both bounds can
    # be outside the visible RF slice.
    fill = (100, 204, 215, int(34 * alpha))
    edge = (134, 238, 244, int(226 * alpha))
    # Amber is deliberately reserved for the tuned RF center: it remains
    # legible over blue/cyan waterfall energy without resembling a signal.
    center_shadow = (2, 7, 11, int(128 * alpha))
    center = (255, 192, 68, int(222 * alpha))
    if raw_right - raw_left < 10:
        # At wide waterfall spans the real filter can be sub-pixel narrow.
        # Show a compact bracket instead of visually falsifying its width.
        bracket_x = clamp((low_x + high_x) / 2, 6.0, canvas_w - 6.0)
        for edge_x in (bracket_x - 4, bracket_x + 4):
            draw_logical_line(edge_x, y0, edge_x, y1, edge, 1)
            draw_logical_line(edge_x, y0 + 5, bracket_x, y0 + 5, edge, 1)
    else:
        draw_logical_rect(left, y0, right, y1, fill)
        for edge_x, cap_direction in ((low_x, 1), (high_x, -1)):
            clipped_edge_x = clamp(edge_x, 0.0, float(canvas_w))
            draw_logical_line(clipped_edge_x, y0, clipped_edge_x, y1, edge, 2)
            draw_logical_line(
                clipped_edge_x,
                y0 + 5,
                clipped_edge_x + cap_direction * 5,
                y0 + 5,
                edge,
                2,
            )
    # At high zoom the whole visible slice may be inside a much wider filter.
    # Rails at the display bounds explicitly communicate that state, rather
    # than making the rectangle look static or missing because its true edges
    # are beyond the current magnified view.
    clipped = raw_left < 0.0 or raw_right > canvas_w
    if raw_left < 0.0:
        draw_logical_line(1, y0 + 9, 1, y1 - 9, edge, 2)
    if raw_right > canvas_w:
        draw_logical_line(canvas_w - 1, y0 + 9, canvas_w - 1, y1 - 9, edge, 2)
    if clipped:
        width_hz = abs(high_cut - low_cut)
        label = f"BW {width_hz / 1000:.2f} kHz"
        label_font = text_cache.font(13, bold=True, family="Cantarell")
        label_w = label_font.size(label)[0]
        label_x1 = canvas_w - 12
        label_x0 = label_x1 - label_w - 14
        draw_logical_rect(label_x0, y0 + 7, label_x1, y0 + 27, (4, 15, 20, int(172 * alpha)))
        draw_text(text_cache, label_x1 - 7, y0 + 17, label, edge[:3], 13, True, False, "rm", alpha, family="Cantarell")
    if 0 <= center_x <= canvas_w:
        # A continuous marker masks a weak, perfectly tuned carrier. Use a
        # fine dashed guide instead, with a clear top reference tick.
        draw_logical_line(center_x - 6, y0 + 2, center_x + 6, y0 + 2, center, 1)
        dash_h = 5
        dash_period = 12
        for dash_y in range(int(y0 + 8), int(y1), dash_period):
            dash_end = min(dash_y + dash_h, y1)
            draw_logical_line(center_x, dash_y, center_x, dash_end, center_shadow, 3)
            draw_logical_line(center_x, dash_y, center_x, dash_end, center, 1)


def draw_filter_setup_panel(text_cache, mode, low_cut, high_cut, custom_width=False):
    x0, y0, x1, y1 = FILTER_PANEL_BOX
    draw_logical_rect(x0, y0, x1, y1, (5, 12, 18, 174))
    draw_logical_line(x0, y0, x1, y0, (163, 190, 196, 132), 1)
    draw_logical_line(x0, y1, x1, y1, (163, 190, 196, 132), 1)
    draw_text(text_cache, 34, y0 + 22, f"FILTER  {mode}", (229, 243, 246), 24, True, True, "lm")
    width_hz = high_cut - low_cut
    draw_text(text_cache, 926, y0 + 22, f"BW {width_hz / 1000:.2f} kHz", (205, 210, 213), 24, True, True, "rm")

    sx0, sy0, sx1, sy1 = FILTER_EDIT_BOX
    view_low_cut, view_high_cut = filter_view_offsets(low_cut, high_cut)
    edit_limit = filter_edit_limit(view_low_cut, view_high_cut)
    carrier_hz = 0.0
    zero_x = filter_x(carrier_hz, sx0, sx1, edit_limit, carrier_hz)
    low_x = filter_x(view_low_cut, sx0, sx1, edit_limit, carrier_hz)
    high_x = filter_x(view_high_cut, sx0, sx1, edit_limit, carrier_hz)
    block_y0 = sy0 + 52
    block_y1 = sy1 - 17
    draw_logical_rect(sx0, sy0, sx1, sy1, (3, 17, 25, 174))
    draw_logical_line(sx0, block_y0, sx1, block_y0, (83, 128, 141, 96), 1)
    draw_logical_line(sx0, block_y1, sx1, block_y1, (83, 128, 141, 96), 1)
    draw_logical_line(zero_x, sy0 + 6, zero_x, sy1 - 6, (185, 220, 224, 150), 2)
    draw_logical_rect(low_x, block_y0, high_x, block_y1, (112, 118, 122, 104))
    draw_logical_line(low_x, block_y0, low_x, block_y1, (207, 213, 216, 255), 3)
    draw_logical_line(high_x, block_y0, high_x, block_y1, (207, 213, 216, 255), 3)
    for handle_x in (low_x, high_x):
        draw_logical_rect(handle_x - 12, block_y0 - 8, handle_x + 12, block_y1 + 8, (166, 172, 176, 188))
        draw_logical_line(handle_x - 4, block_y0 + 5, handle_x - 4, block_y1 - 5, (47, 51, 54, 220), 2)
        draw_logical_line(handle_x + 4, block_y0 + 5, handle_x + 4, block_y1 - 5, (47, 51, 54, 220), 2)
    draw_text(text_cache, (low_x + high_x) / 2, (block_y0 + block_y1) / 2, "PASSBAND", (236, 239, 241), 14, True, True, "cm")
    draw_text(text_cache, sx0 + 8, sy0 + 13, "LEFT EDGE", (202, 208, 211), 13, True, True, "lm")
    draw_text(text_cache, sx1 - 8, sy0 + 13, "RIGHT EDGE", (202, 208, 211), 13, True, True, "rm")
    draw_text(text_cache, sx0 + 8, sy0 + 29, format_filter_cut(view_low_cut), (225, 229, 231), 23, True, True, "lm")
    draw_text(text_cache, sx1 - 8, sy0 + 29, format_filter_cut(view_high_cut), (225, 229, 231), 23, True, True, "rm")
    draw_text(text_cache, zero_x, sy1 - 7, "CARRIER", (152, 181, 187), 12, True, True, "cm")
    preset_index = filter_preset_index(width_hz)
    is_preset = preset_index is not None and not custom_width
    draw_filter_width_control(text_cache, FILTER_WIDTH_MINUS_BOX, "-")
    draw_filter_width_control(text_cache, FILTER_WIDTH_PLUS_BOX, "+")
    label_color = (236, 239, 241) if is_preset else (199, 204, 207)
    label_fill = (86, 91, 95, 104) if is_preset else (54, 58, 62, 78)
    label_line = (190, 196, 199, 172) if is_preset else (143, 149, 153, 126)
    lx0, ly0, lx1, ly1 = FILTER_WIDTH_LABEL_BOX
    draw_logical_rect(lx0, ly0, lx1, ly1, label_fill)
    draw_logical_line(lx0, ly0, lx1, ly0, label_line, 1)
    draw_logical_line(lx0, ly1, lx1, ly1, label_line, 1)
    draw_logical_line(lx0, ly0, lx0, ly1, label_line, 1)
    draw_logical_line(lx1, ly0, lx1, ly1, label_line, 1)
    if is_preset:
        choice_name, choice_width = FILTER_WIDTH_PRESETS[preset_index]
        label = f"{choice_name}  {format_filter_width(choice_width)}"
    else:
        label = f"CUSTOM  {format_filter_width(width_hz)}"
    draw_text(text_cache, (lx0 + lx1) / 2, (ly0 + ly1) / 2, label, label_color, 24, True, True, "cm")


def format_zoom_span(span_khz):
    if span_khz >= 1000:
        return f"{span_khz / 1000:.1f} MHz"
    return f"{span_khz:.1f} kHz"


def draw_zoom_osd(text_cache, zoom, span_khz, alpha):
    alpha = clamp(int(alpha), 0, 255)
    if alpha <= 0:
        return
    x0, y0, x1, y1 = 240, 63, 720, 161
    green = (72, 255, 122, alpha)
    dim = (72, 255, 122, int(alpha * 0.18))
    soft = (72, 255, 122, int(alpha * 0.35))
    draw_logical_rect(x0, y0, x1, y1, (0, 8, 4, int(alpha * 0.42)))
    for offset, line_alpha in ((32, 0.20), (64, 0.12)):
        y = y0 + offset
        draw_logical_line(x0 + 4, y, x1 - 4, y, (72, 255, 122, int(alpha * line_alpha)), 1)
    digital_factor = kiwi.DIGITAL_ZOOM_FACTORS.get(int(zoom))
    zoom_label = f"ZOOM DIGITAL {digital_factor:.0f}x" if digital_factor else "ZOOM"
    draw_text(text_cache, x0 + 18, y0 + 22, zoom_label, green[:3], 28, True, True, "lm")
    draw_text(text_cache, x1 - 18, y0 + 22, format_zoom_span(span_khz), green[:3], 28, True, True, "rm")

    track_x0 = x0 + 24
    track_x1 = x1 - 24
    base_y = y0 + 81
    draw_logical_line(track_x0, base_y, track_x1, base_y, soft, 3)
    bar_w = 17
    for level in range(kiwi.DISPLAY_MAX_ZOOM + 1):
        x = int(round(track_x0 + (track_x1 - track_x0) * level / kiwi.DISPLAY_MAX_ZOOM))
        fill = green if level <= zoom else dim
        h = 36 if level == zoom else 24
        draw_logical_rect(x - bar_w / 2, base_y - h, x + bar_w / 2, base_y - 1, fill)


def draw_rc28_mode_osd(text_cache, mode, alpha):
    """Brief hardware-mode acknowledgement for the Icom RC-28 dial."""
    alpha = clamp(int(alpha), 0, 255)
    if alpha <= 0:
        return
    x0, y0, x1, y1 = 330, 72, 630, 130
    green = (72, 255, 122, alpha)
    draw_logical_rect(x0, y0, x1, y1, (0, 9, 5, int(alpha * 0.58)))
    draw_logical_line(x0 + 10, y1 - 8, x1 - 10, y1 - 8, (72, 255, 122, int(alpha * 0.42)), 1)
    draw_text(text_cache, x0 + 16, (y0 + y1) / 2, "RC-28", green[:3], 22, True, True, "lm")
    draw_text(text_cache, x1 - 16, (y0 + y1) / 2, mode, green[:3], 30, True, True, "rm")


def frequency_identity_osd_bounds(candidates):
    """Shared geometry for drawing and the exact-frequency touch target."""
    max_rows = min(3, len(candidates))
    x0 = 28
    x1 = min(rf_canvas_width() - 18, 790)
    y0 = 452
    return x0, y0, x1, y0 + 84 + max_rows * 56


def frequency_identity_schedule_touch_box(candidates):
    """The scheduled RF readout is the only tuning action in the OSD."""
    x0, y0, x1, _y1 = frequency_identity_osd_bounds(candidates)
    return max(x0 + 430, x1 - 220), y0 + 2, x1 - 8, y0 + 44


def draw_frequency_identity_osd(text_cache, frequency_khz, candidates, receiver_context, alpha):
    """Show database schedule candidates with explicit UTC/receiver context."""
    alpha = int(clamp(alpha, 0, 255))
    if alpha <= 0 or not candidates:
        return
    x0, y0, x1, y1 = frequency_identity_osd_bounds(candidates)
    max_rows = min(3, len(candidates))
    cyan = (92, 222, 247)
    draw_logical_rect(x0, y0, x1, y1, (5, 15, 25, int(alpha * 0.88)))
    draw_logical_line(x0, y0, x1, y0, (*cyan, int(alpha * 0.96)), 2)
    scheduled_frequency_khz = float(candidates[0].get("frequency_khz", frequency_khz))
    display_policy = BROADCAST_IDENTIFICATION_POLICY["display"]
    title = str(display_policy.get("title") or "SCHEDULED BROADCASTS").upper()
    source_label = str(candidates[0].get("source", "Shortwave DB")).upper()
    source_key = "shortwave_live" if source_label == "SHORTWAVE.LIVE" else "shortwave_db"
    source_policy = BROADCAST_IDENTIFICATION_POLICY["sources"].get(source_key, {})
    schedule_label = "UTC ACTIVE" if source_policy.get("active_schedule_required") else "UTC SCHEDULE"
    utc_label = time.strftime("%H:%M UTC", time.gmtime())
    context = receiver_context or {}
    receiver_label = str(context.get("label") or "SELECTED RECEIVER").upper()
    receiver_source = str(context.get("source") or "RECEIVER GPS ?").upper()
    receiver_coordinates = context.get("coordinates")
    draw_text(text_cache, x0 + 16, y0 + 23, title, (224, 248, 253), 24, True, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x1 - 16, y0 + 23, f"SCHEDULE {scheduled_frequency_khz / 1000.0:.3f} MHz", (150, 232, 249), 20, True, False, "rm", family="Liberation Sans")
    receiver_detail = fit_station_text(
        text_cache, f"RX {receiver_label}", x1 - x0 - 250, 15, False, False,
        family="Liberation Sans",
    )
    draw_text(text_cache, x0 + 16, y0 + 49, receiver_detail, (166, 211, 220), 15, False, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x1 - 16, y0 + 49, f"{receiver_source} · {utc_label}", (150, 185, 196), 15, True, False, "rm", family="Liberation Sans")
    draw_text(text_cache, x0 + 16, y0 + 70, f"{source_label} · {schedule_label}", (116, 187, 202), 14, True, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x1 - 16, y0 + 70, "DIST / PWR", (150, 185, 196), 15, True, False, "rm", family="Liberation Sans")
    for index, candidate in enumerate(candidates[:max_rows]):
        row_y = y0 + 98 + index * 56
        if index:
            draw_logical_line(x0 + 14, row_y - 24, x1 - 14, row_y - 24, (98, 151, 166, int(alpha * 0.35)), 1)
        distance = frequency_identity_distance_km(candidate, receiver_coordinates)
        distance_label = f"{int(round(distance)):,} km" if distance is not None else "DIST ?"
        # The flag intentionally spans both information rows. It acts as a
        # compact country marker, not a tiny inline ornament on the detail row.
        flag_x = x0 + 16
        flag_y = row_y - 13
        flag_width = 54
        flag_height = 36
        text_x = flag_x + flag_width + 12
        station = fit_station_text(text_cache, candidate["station"], x1 - text_x - 218, 23, True, False, family="Liberation Sans")
        power_kw = str(candidate.get("power_kw") or "").strip()
        if power_kw.casefold() in {"", "-", "?", "0", "0.0", "0 kw"}:
            power_label = "PWR N/L"
        elif re.fullmatch(r"[0-9]+(?:\.[0-9]+)?", power_kw):
            power_label = f"PWR {power_kw} kW"
        else:
            power_label = f"PWR {power_kw}"
        detail_parts = [
            part for part in (
                candidate.get("transmitter"), candidate.get("language"),
                candidate.get("time"),
            ) if part
        ]
        detail = fit_station_text(text_cache, " · ".join(detail_parts), x1 - text_x - 218, 17, False, False, family="Liberation Sans")
        draw_country_flag(candidate.get("country"), flag_x, flag_y, flag_width, flag_height, alpha / 255.0)
        draw_text(text_cache, text_x, row_y, station, (238, 248, 250), 23, True, False, "lm", family="Liberation Sans")
        draw_text(text_cache, text_x, row_y + 24, detail, (174, 202, 209), 17, False, False, "lm", family="Liberation Sans")
        draw_text(text_cache, x1 - 16, row_y - 2, distance_label, (126, 232, 250), 19, True, False, "rm", family="Liberation Sans")
        power_color = (139, 220, 235) if power_label != "PWR N/L" else (183, 205, 211)
        draw_text(text_cache, x1 - 16, row_y + 22, power_label, power_color, 18, True, False, "rm", family="Liberation Sans")


def active_wspr_decode_tiles(tiles, monitor_manager):
    """Return only sessions with a live wsprd process, in tile display order."""
    active = []
    for tile in tiles:
        session = monitor_manager.sessions.get(str(tile.get("id", "")))
        if session is None:
            continue
        snapshot = session.snapshot()
        if snapshot.get("decode_status") == "DECODING":
            active.append((tile, snapshot))
    return tuple(active)


def draw_wspr_decode_osd(text_cache, active_tiles, y0):
    """Persistent main-waterfall marker for an actual, active wsprd decode."""
    if not active_tiles:
        return
    tile, snapshot = active_tiles[0]
    x1 = rf_canvas_width() - 20
    width = min(510, x1 - 40)
    x0 = int((rf_canvas_width() - width) / 2)
    y0 = int(clamp(y0, 8, LOGICAL_H - 76))
    y1 = y0 + 58
    pulse = 0.55 + 0.45 * (0.5 + 0.5 * math.sin(time.monotonic() * 5.5))
    amber = (251, 186, 79)
    draw_logical_rect(x0, y0, x1, y1, (18, 13, 5, 214))
    draw_logical_line(x0, y0, x1, y0, (*amber, 235), 1.5)
    draw_logical_line(x0, y1, x1, y1, (*amber, 160), 1)
    dot_x, dot_y = x0 + 22, y0 + 21
    draw_logical_circle(dot_x, dot_y, 7 + 3 * pulse, (*amber, int(65 + 95 * pulse)), 24, True)
    draw_logical_circle(dot_x, dot_y, 5, (*amber, 245), 20)
    draw_text(text_cache, x0 + 40, y0 + 20, "WSPR DECODING", (255, 224, 160), 20, True, True, "lm", family="Liberation Sans")
    band = str(tile.get("band", "?"))
    receiver = fit_station_text(text_cache, str(tile.get("name", "CURRENT RECEIVER")), 215, 15, True, False, "Liberation Sans")
    profile = str(snapshot.get("decode_detail", "NORMAL")).upper() or "NORMAL"
    detail = f"{band} m  ·  {receiver}  ·  {profile}"
    if len(active_tiles) > 1:
        detail += f"  ·  +{len(active_tiles) - 1} QUEUED"
    draw_text(text_cache, x0 + 18, y0 + 43, detail, (239, 199, 120), 15, True, False, "lm", family="Liberation Sans")


def station_page_max(stations):
    visible = PICKER_COLS * PICKER_ROWS
    remaining = max(0, len(stations) - visible)
    # Keep every page origin on a complete rendered row so drag scrolling
    # never changes a tile's target beneath a finger.
    return ((remaining + PICKER_COLS - 1) // PICKER_COLS) * PICKER_COLS


def station_tile(index, scroll):
    x0, y0, x1, y1 = PICKER_BOX
    pad = 4
    gap = 3
    grid_x0 = x0 + pad
    grid_y0 = y0 + PICKER_HEADER_H + pad
    cell_w = (x1 - x0 - 2 * pad - (PICKER_COLS - 1) * gap) // PICKER_COLS
    cell_h = (y1 - grid_y0 - pad - (PICKER_ROWS - 1) * gap) // PICKER_ROWS
    # `scroll` is expressed in station entries. Preserve a whole row when
    # there are multiple columns, while allowing the list to slide between
    # rows instead of jumping one entire tile at a time.
    scroll_rows = float(scroll) / max(1, PICKER_COLS)
    col = index % PICKER_COLS
    row = index // PICKER_COLS - scroll_rows
    if row <= -1 or row >= PICKER_ROWS:
        return None
    left = grid_x0 + col * (cell_w + gap)
    top = grid_y0 + row * (cell_h + gap)
    return left, top, left + cell_w, top + cell_h


def station_at(x, y, stations, scroll):
    for idx, _station in enumerate(stations):
        box = station_tile(idx, scroll)
        if box and contains(box, x, y):
            return idx
    return None


def menu_metrics():
    x0, y0, x1, y1 = MENU_BOX
    pad = 12
    gap = 10
    item_w = (x1 - x0 - 2 * pad - (MENU_COLS - 1) * gap) / MENU_COLS
    item_h = (y1 - y0 - 2 * pad - (MENU_ROWS - 1) * gap) / MENU_ROWS
    return x0, y0, x1, y1, pad, gap, item_w, item_h


def menu_max_scroll():
    # The Home grid is deliberately finite: no hidden horizontal pages.
    return 0.0


def menu_item_box(index, scroll):
    x0, y0, _x1, _y1, pad, gap, item_w, item_h = menu_metrics()
    col = index % MENU_COLS
    row = index // MENU_COLS
    if row >= MENU_ROWS:
        return None
    # The second row remains left-justified, like the first, so operators can
    # scan a stable grid without a competing close target.
    left = x0 + pad + col * (item_w + gap)
    top = y0 + pad + row * (item_h + gap)
    return left, top, left + item_w, top + item_h


def menu_at(x, y, scroll):
    if not contains(MENU_BOX, x, y):
        return None
    for idx in range(len(MENU_ITEMS)):
        box = menu_item_box(idx, scroll)
        if box and contains(box, x, y):
            return idx
    return None


def draw_menu_icon(surface, kind, cx, cy, color, dim):
    if kind == "local_rx":
        # LAN: the familiar hub-and-spokes local-network topology. It is
        # deliberately literal, distinct from both the global receiver globe
        # and the abstract constellation tool.
        mono = (224, 237, 239, 238)
        stroke = 2
        top = pygame.Rect(cx - 9, cy - 22, 18, 13)
        pygame.draw.rect(surface, mono, top, stroke, border_radius=5)
        bus_y = cy - 2
        pygame.draw.line(surface, mono, (cx, top.bottom + 3), (cx, bus_y), stroke)
        pygame.draw.line(surface, mono, (cx - 20, bus_y), (cx + 20, bus_y), stroke)
        for node_x in (cx - 20, cx, cx + 20):
            node = pygame.Rect(node_x - 7, cy + 7, 14, 11)
            pygame.draw.line(surface, mono, (node_x, bus_y), (node_x, node.top - 3), stroke)
            pygame.draw.rect(surface, mono, node, stroke, border_radius=4)
    elif kind == "rx":
        # A compact, swept spherical wireframe based on the receiver-globe
        # reference, not a set of free-floating orbital rings.
        mono = (218, 228, 230, 225)
        globe_y = cy - 2

        def quadratic_curve(start, control, end, width):
            points = []
            for index in range(21):
                t = index / 20
                inv_t = 1 - t
                points.append((round(inv_t * inv_t * start[0] + 2 * inv_t * t * control[0] + t * t * end[0]), round(inv_t * inv_t * start[1] + 2 * inv_t * t * control[1] + t * t * end[1])))
            pygame.draw.lines(surface, mono, False, points, width)

        pygame.draw.circle(surface, mono, (cx, globe_y), 25, 2)
        # Four diagonal bands echo the attached woven-globe mark.
        quadratic_curve((cx - 18, globe_y - 18), (cx, globe_y - 30), (cx + 20, globe_y - 14), 3)
        quadratic_curve((cx - 25, globe_y - 8), (cx, globe_y + 5), (cx + 25, globe_y - 1), 3)
        quadratic_curve((cx - 25, globe_y + 5), (cx, globe_y + 18), (cx + 22, globe_y + 13), 3)
        quadratic_curve((cx - 17, globe_y + 18), (cx, globe_y + 30), (cx + 18, globe_y + 20), 3)
        # The angled meridians complete the woven spherical form.
        quadratic_curve((cx - 7, globe_y - 24), (cx - 21, globe_y - 1), (cx - 5, globe_y + 25), 3)
        quadratic_curve((cx + 8, globe_y - 24), (cx + 22, globe_y + 1), (cx + 7, globe_y + 24), 3)
    elif kind == "radio":
        pygame.draw.rect(surface, color, (cx - 27, cy - 17, 54, 36), 3, border_radius=5)
        pygame.draw.line(surface, color, (cx - 17, cy - 24), (cx + 18, cy - 36), 3)
        pygame.draw.circle(surface, dim, (cx + 14, cy + 1), 8, 3)
        pygame.draw.line(surface, dim, (cx - 18, cy - 3), (cx - 2, cy - 3), 3)
        pygame.draw.line(surface, dim, (cx - 18, cy + 8), (cx - 4, cy + 8), 3)
    elif kind == "display":
        for offset, knob_x in ((-16, -8), (0, 15), (16, -18)):
            pygame.draw.line(surface, color, (cx - 28, cy + offset), (cx + 28, cy + offset), 3)
            pygame.draw.circle(surface, dim, (cx + knob_x, cy + offset), 7, 3)
    elif kind == "filter":
        pygame.draw.line(surface, dim, (cx - 32, cy + 18), (cx + 32, cy + 18), 2)
        pygame.draw.rect(surface, (74, 222, 225, 76), (cx - 15, cy - 20, 30, 38))
        pygame.draw.line(surface, color, (cx - 15, cy - 24), (cx - 15, cy + 22), 3)
        pygame.draw.line(surface, color, (cx + 15, cy - 24), (cx + 15, cy + 22), 3)
        pygame.draw.line(surface, dim, (cx, cy - 30), (cx, cy + 25), 2)
    elif kind == "audio":
        # Supplied speaker mark, retained as an outlined horn with two open
        # broadcast arcs and simply inverted for this dark instrument surface.
        speaker = (232, 242, 244, 240)
        pygame.draw.rect(surface, speaker, (cx - 30, cy - 15, 18, 30), 5, border_radius=7)
        pygame.draw.lines(surface, speaker, True, ((cx - 13, cy - 15), (cx + 11, cy - 31), (cx + 11, cy + 31), (cx - 13, cy + 15)), 5)
        pygame.draw.arc(surface, speaker, (cx - 10, cy - 22, 38, 44), math.radians(-58), math.radians(58), 6)
        pygame.draw.arc(surface, speaker, (cx - 17, cy - 34, 62, 68), math.radians(-58), math.radians(58), 6)
    elif kind == "dual":
        # Two stacked RF panes: a clear, monochrome Dual VFO mark that stays
        # readable at the deliberately restrained menu-icon scale.
        for offset, accent in ((-15, color), (15, dim)):
            pygame.draw.rect(surface, accent, (cx - 31, cy + offset - 10, 62, 20), 2, border_radius=3)
            pygame.draw.line(surface, accent, (cx - 21, cy + offset + 3), (cx - 7, cy + offset - 4), 2)
            pygame.draw.line(surface, accent, (cx - 7, cy + offset - 4), (cx + 6, cy + offset + 4), 2)
            pygame.draw.line(surface, accent, (cx + 6, cy + offset + 4), (cx + 20, cy + offset - 2), 2)
    elif kind == "tests":
        # Checklist fallback matching the supplied diagnostics artwork.
        pygame.draw.rect(surface, color, (cx - 23, cy - 31, 46, 62), 3, border_radius=3)
        pygame.draw.line(surface, dim, (cx - 13, cy - 12), (cx - 5, cy - 4), 3)
        pygame.draw.line(surface, dim, (cx - 5, cy - 4), (cx + 8, cy - 19), 3)
        pygame.draw.line(surface, color, (cx - 13, cy + 4), (cx + 13, cy + 4), 3)
        pygame.draw.line(surface, color, (cx - 13, cy + 16), (cx + 13, cy + 16), 3)
    elif kind == "settings":
        pygame.draw.circle(surface, color, (cx, cy), 17, 3)
        pygame.draw.circle(surface, dim, (cx, cy), 6, 3)
        for angle in range(0, 360, 45):
            radians = math.radians(angle)
            x0 = cx + round(math.cos(radians) * 20)
            y0 = cy + round(math.sin(radians) * 20)
            x1 = cx + round(math.cos(radians) * 27)
            y1 = cy + round(math.sin(radians) * 27)
            pygame.draw.line(surface, color, (x0, y0), (x1, y1), 4)
    elif kind == "digital":
        # An intentionally simple sampled square-wave mark for digital modes.
        points = ((cx - 29, cy + 15), (cx - 19, cy + 15), (cx - 19, cy - 15), (cx - 2, cy - 15), (cx - 2, cy + 15), (cx + 15, cy + 15), (cx + 15, cy - 15), (cx + 29, cy - 15))
        pygame.draw.lines(surface, color, False, points, 4)
        pygame.draw.circle(surface, dim, (cx - 21, cy - 23), 3)
        pygame.draw.circle(surface, dim, (cx + 18, cy + 23), 3)
    elif kind == "rf":
        # Broadcast antenna: signal elements belong at the mast's upper end.
        pygame.draw.line(surface, color, (cx, cy - 22), (cx, cy + 16), 4)
        pygame.draw.line(surface, color, (cx - 19, cy + 25), (cx + 19, cy + 25), 3)
        pygame.draw.line(surface, color, (cx - 17, cy + 25), (cx, cy + 7), 3)
        pygame.draw.line(surface, color, (cx + 17, cy + 25), (cx, cy + 7), 3)
        pygame.draw.line(surface, color, (cx - 12, cy - 25), (cx, cy - 16), 3)
        pygame.draw.line(surface, color, (cx + 12, cy - 25), (cx, cy - 16), 3)
        pygame.draw.circle(surface, color, (cx, cy - 23), 3)
    elif kind == "stats":
        # Three compact instrument bars denote live receiver/system telemetry.
        for offset, height in ((-20, 17), (0, 29), (20, 39)):
            pygame.draw.rect(surface, color, (cx + offset - 6, cy + 24 - height, 12, height), 3, border_radius=2)
        pygame.draw.line(surface, dim, (cx - 31, cy + 25), (cx + 31, cy + 25), 2)
    else:
        pygame.draw.circle(surface, color, (cx, cy), 24, 3)
        pygame.draw.line(surface, color, (cx, cy - 4), (cx, cy + 20), 3)
        pygame.draw.circle(surface, color, (cx, cy - 20), 3)


def menu_icon_texture(text_cache, kind, label, width=132, height=112):
    """Build a menu tile at its eventual raster size to avoid texture blur."""
    key = f"menu_asset_{kind}_{label}_{width}x{height}"
    cached = text_cache.cache.get(("surface", key))
    if cached is not None:
        return cached
    surface = pygame.Surface((width, height), pygame.SRCALPHA)
    try:
        if kind in ("local_rx", "network"):
            # Network is the configuration side of the same local-LAN path
            # represented by LOCAL RX, so reuse that exact hub glyph.
            draw_menu_icon(surface, "local_rx", width // 2, max(24, height // 2 - 12),
                           (232, 248, 250, 232), (82, 235, 231, 150))
        else:
            asset_path = MENU_ICON_ASSET_DIR / MENU_ICON_FILENAMES.get(kind, f"{kind}.png")
            icon = pygame.image.load(str(asset_path)).convert_alpha()
            # Keep the supplied vector-derived art deliberately understated in the
            # compact menu. Its transparent alpha allows one clean 30% reduction.
            icon_size = round(icon.get_width() * 0.70)
            icon = pygame.transform.smoothscale(icon, (icon_size, icon_size))
            icon_y = max(0, (height - 26 - icon_size) // 2)
            surface.blit(icon, ((width - icon.get_width()) // 2, icon_y))
    except (pygame.error, OSError):
        # Keep development builds usable if the optional icon package is absent.
        color = (232, 248, 250, 232)
        dim = (82, 235, 231, 150)
        draw_menu_icon(surface, kind, width // 2, max(24, height // 2 - 12), color, dim)
    label_surface = text_cache.font(15, bold=True, family="Liberation Sans").render(label, True, (207, 221, 224))
    surface.blit(label_surface, ((width - label_surface.get_width()) // 2, height - 26))
    return text_cache.surface_texture(key, surface)


def draw_main_menu(text_cache, scroll):
    x0, y0, x1, y1 = MENU_BOX
    # Let the waterfall remain legible behind a single calm, temporary veil.
    draw_logical_rect(x0, y0, x1, y1, (5, 12, 18, 222))
    draw_logical_line(x0 + 12, y0, x1 - 12, y0, (174, 201, 205, 72), 1)
    for idx, (kind, label) in enumerate(MENU_ITEMS):
        box = menu_item_box(idx, scroll)
        if box is None:
            continue
        bx0, by0, bx1, by1 = box
        if bx1 < x0 or bx0 > x1:
            continue
        target_w = min(132, bx1 - bx0 - 12)
        target_h = min(92, by1 - by0 - 4)
        target_x = bx0 + ((bx1 - bx0) - target_w) / 2
        target_y = by0 + ((by1 - by0) - target_h) / 2
        tex, tex_w, tex_h = menu_icon_texture(text_cache, kind, label, int(target_w), int(target_h))
        draw_textured_quad(tex, target_x, target_y, target_x + target_w, target_y + target_h, 0, 0, 1, 1)


def desktop_1280_nav_box(index):
    """Persistent 2-column Home navigation rail for the 1280x480 desktop test."""
    col = index % 2
    row = index // 2
    x0 = DESKTOP_1280_MAIN_W + 7 + col * 125
    y0 = DESKTOP_1280_TOP_H + 8 + row * 96
    return x0, y0, x0 + 117, y0 + 88


def draw_desktop_1280_navigation(text_cache):
    if not DESKTOP_1280_MODE:
        return
    x0 = DESKTOP_1280_MAIN_W
    draw_native_rect(x0, DESKTOP_1280_TOP_H, NATIVE_W, NATIVE_H, (6, 13, 19, 246))
    for index, (kind, label) in enumerate(MENU_ITEMS):
        bx0, by0, bx1, by1 = desktop_1280_nav_box(index)
        draw_native_rect(bx0, by0, bx1, by1, (17, 29, 38, 218))
        draw_native_line(bx0, by0, bx1, by0, (125, 147, 158, 118), 1)
        draw_native_line(bx0, by1, bx1, by1, (32, 50, 61, 170), 1)
        draw_native_line(bx0, by0, bx0, by1, (66, 85, 96, 140), 1)
        draw_native_line(bx1, by0, bx1, by1, (32, 50, 61, 170), 1)
        tile_w = bx1 - bx0 - 8
        tile_h = by1 - by0 - 8
        tex, _tex_w, _tex_h = menu_icon_texture(text_cache, kind, label, tile_w, tile_h)
        draw_native_textured_quad(tex, bx0 + 4, by0 + 4, bx1 - 4, by1 - 4, alpha=0.96)


LCD_NAV_X0 = 1024
LCD_NAV_TOP_MIN = 88
# The right rail is an instrument launcher, not an iPad home screen. Keep its
# 2x4 composition but give each action 20% less visual mass and generous
# gutters around it, so the waterfall remains the primary surface.
LCD_NAV_TILE_W = 94
LCD_NAV_TILE_H = 82
LCD_NAV_GAP = 20
LCD_DRAWER_HEADER_H = 64
LCD_DRAWER_HEADING_COLOR = (151, 169, 174)
LCD_DRAWER_HEADING_SIZE = 13
VFO_FONT_FAMILY = "Oxanium"
# One face across the radio avoids a visual hand-off between the Home rail,
# large VFO readout and Dual VFO. Oxanium remains clear at the small rail size.
COMPACT_FREQUENCY_FONT_FAMILY = "Oxanium"
VFO_NEON_COLOR = (115, 255, 177)
# Shared active-line half-height for every continuous control.
SLIDER_STEM_HALF_HEIGHT = 3
# Keep enough vertical space for a readable passband scale and silhouette.
LCD_HOME_PASSBAND_HEIGHT = 89
# The auxiliary VFO readout sits directly above the mode matrix in the LCD's
# right rail. It is intentionally separate from (and does not replace) the
# main frequency display in the top instrument strip.
LCD_ANNUNCIATOR_BOX = (1031, 0, 1273, 266)
# This is updated by the render loop. Keeping the progress here lets drawing
# and hit-testing share the same top-to-bottom drawer reveal.
LCD_RADIO_DRAWER_PROGRESS = 0.0


def lcd_content_bottom():
    """Bottom edge reserved for live controls, above ruler and status."""
    return LOGICAL_H - BOTTOM_STATUS_H - BOTTOM_RULER_H


def lcd_rail_bottom():
    """The permanent 256 px Home rail owns the full logical height.

    The lower status strip belongs only to the 1024 px RF canvas.  Keeping
    this independent makes Home a continuous black instrument panel and
    gives its controls the otherwise unused lower space.
    """
    return LOGICAL_H


def lcd_radio_drawer_close_box():
    x0, _y0, x1, y1 = radio_panel_box()
    # The mode choices are top-justified. A broad, isolated bottom return is
    # easy to find and cannot be confused with a mode-family control.
    return x0 + 10, y1 - 78, x1 - 10, y1 - 10


def lcd_radio_drawer_reveal_y():
    """Lower edge of the downward-opening LCD mode drawer."""
    _x0, y0, _x1, y1 = radio_panel_box()
    return y0 + (y1 - y0) * LCD_RADIO_DRAWER_PROGRESS


def lcd_nav_top(item_count=None):
    """Bottom-align only the rows actually present in this rail view."""
    item_count = len(MENU_ITEMS) if item_count is None else max(1, int(item_count))
    rows = math.ceil(item_count / 2)
    tiles_h = rows * LCD_NAV_TILE_H + (rows - 1) * LCD_NAV_GAP
    return max(LCD_NAV_TOP_MIN, lcd_rail_bottom() - LCD_CONTROL_GAP - tiles_h)


def lcd_home_mode_grid_geometry(show_compact_readouts=True):
    """Return the fixed-size Home mode grid within its reserved rail area.

    Expanded presentation removes the duplicate compact VFO instruments.  It
    must not turn that freed area into giant mode buttons: use the same
    two-row mode grid height in both presentations and simply top-align it.
    """
    _x0, y0, _x1, y1 = LCD_ANNUNCIATOR_BOX
    # These are status annunciators, not primary action buttons. A restrained
    # 15% reduction keeps the group calm without making the labels fussy.
    gap = 4
    # Keep a distinct 17 px air gap beneath the compact S-meter scale. The
    # mode annunciators are a separate control group, not its bottom label.
    compact_grid_y0 = 190
    compact_cell_h = 31
    grid_y0 = compact_grid_y0 if show_compact_readouts else 28
    return grid_y0, compact_cell_h, gap


def lcd_home_mode_grid_bottom(show_compact_readouts=True):
    grid_y0, cell_h, gap = lcd_home_mode_grid_geometry(show_compact_readouts)
    return LCD_ANNUNCIATOR_BOX[1] + grid_y0 + 2 * cell_h + gap


def compact_frequency_touch_box():
    """The open compact frequency digits, distinct from the mode matrix."""
    x0, y0, x1, _y1 = LCD_ANNUNCIATOR_BOX
    return x0 + 4, y0 + 12, x1 - 4, y0 + 83


def frequency_band_context(freq_khz, mode=""):
    """Return a concise, frequency-derived band/sub-band operating label."""
    freq_khz = float(freq_khz or 0.0)
    mode = str(mode or "").upper()
    ham_band = next((label for low, high, label in HAM_BANDS if low <= freq_khz <= high), None)
    if ham_band:
        if any(low <= freq_khz <= high for low, high in FT8_SUBBANDS):
            return f"{ham_band} · FT8", "ham"
        if any(low <= freq_khz <= high for low, high in CW_SUBBANDS):
            return f"{ham_band} · CW", "ham"
        # AM/SAM/DRM listeners normally care more about the shortwave meter
        # band than an overlapping amateur allocation, especially at 41 m.
        if mode not in ("AM", "AMN", "AMW", "SAM", "SAU", "SAL", "SAS", "QAM", "DRM"):
            return f"{ham_band} · HAM", "ham"
    sw_band = next((label for low, high, label in SW_BROADCAST_BANDS if low <= freq_khz <= high), None)
    if sw_band:
        suffix = "AM" if sw_band in ("LW", "MW") else "SW AM"
        return f"{sw_band} · {suffix}", "broadcast"
    if ham_band:
        return f"{ham_band} · HAM", "ham"
    return "HF · GENERAL", "general"


def compact_band_context_touch_box():
    """A real touch target for the persistent compact band indicator."""
    x0, y0, x1, _y1 = LCD_ANNUNCIATOR_BOX
    return x0 + 4, y0 + 78, x1 - 4, y0 + 105


def main_band_context_box(text_cache, freq_khz):
    """Place the large-layout band tag beside, never over, the VFO digits."""
    freq_box = frequency_display_box(text_cache, freq_khz)
    x1 = freq_box[0] - 12
    x0 = max(HOME_BOX[2] + 14, x1 - 142)
    return x0, 13, x1, 43


def draw_band_context_chip(text_cache, box, freq_khz, mode, compact=False):
    """Render the band location as a neutral, quiet text annunciator."""
    x0, y0, x1, y1 = box
    label, _kind = frequency_band_context(freq_khz, mode)
    # The band label identifies context; it should never compete with the
    # frequency by looking like a coloured button or a separate status lamp.
    color = (171, 178, 181) if compact else (188, 195, 197)
    size = 17 if compact else 18
    draw_text(text_cache, (x0 + x1) / 2, (y0 + y1) / 2 + 0.5, label, color, size, True, False, "cm", family="Liberation Sans")


def band_navigation_panel_box():
    """Large lower-sheet bounds, leaving the permanent status strip visible."""
    x0, x1 = 18, rf_canvas_width() - 18
    y1 = lcd_content_bottom() - 8
    return x0, max(148, y1 - 360), x1, y1


def band_navigation_layout():
    """Return touch-safe preset cells for the lower band sheet."""
    x0, y0, x1, y1 = band_navigation_panel_box()
    header_h, gap, columns = 47, 8, 6
    grid_y0 = y0 + header_h + 10
    rows = math.ceil(len(BAND_NAV_PRESETS) / columns)
    cell_w = (x1 - x0 - 20 - gap * (columns - 1)) / columns
    cell_h = (y1 - grid_y0 - 12 - gap * (rows - 1)) / rows
    cells = []
    for index, preset in enumerate(BAND_NAV_PRESETS):
        col, row = index % columns, index // columns
        left = x0 + 10 + col * (cell_w + gap)
        top = grid_y0 + row * (cell_h + gap)
        cells.append((preset, (left, top, left + cell_w, top + cell_h)))
    return {
        "panel": (x0, y0, x1, y1),
        "close": (x1 - 66, y0 + 8, x1 - 12, y0 + header_h - 7),
        "cells": cells,
    }


def band_navigation_action_at(x, y):
    boxes = band_navigation_layout()
    if contains(boxes["close"], x, y):
        return "close"
    for index, (_preset, box) in enumerate(boxes["cells"]):
        if contains(box, x, y):
            return index
    return None


def draw_band_navigation(text_cache, freq_khz, mode):
    """Touch-first HF/SW navigator with enough button size for the LCD."""
    boxes = band_navigation_layout()
    x0, y0, x1, y1 = boxes["panel"]
    draw_logical_rect(x0, y0, x1, y1, (5, 13, 19, 241))
    draw_logical_line(x0 + 14, y0, x1 - 14, y0, (143, 190, 198, 176), 1)
    draw_text(text_cache, x0 + 18, y0 + 24, "BAND NAVIGATION", (226, 242, 244), 20, True, False, "lm", family="Liberation Sans")
    context, _kind = frequency_band_context(freq_khz, mode)
    draw_text(text_cache, x0 + 232, y0 + 24, context, (126, 187, 196), 15, True, False, "lm", family="Liberation Sans")
    close = boxes["close"]
    draw_logical_rect(*close, (25, 53, 66, 232))
    for ax0, ay0, ax1, ay1 in ((close[0], close[1], close[2], close[1]), (close[0], close[3], close[2], close[3]), (close[0], close[1], close[0], close[3]), (close[2], close[1], close[2], close[3])):
        draw_logical_line(ax0, ay0, ax1, ay1, (115, 215, 229, 216), 1)
    draw_logical_line(close[0] + 19, (close[1] + close[3]) / 2, close[2] - 17, (close[1] + close[3]) / 2, (235, 250, 251, 255), 2)
    draw_logical_line(close[0] + 19, (close[1] + close[3]) / 2, close[0] + 30, close[1] + 13, (235, 250, 251, 255), 2)
    draw_logical_line(close[0] + 19, (close[1] + close[3]) / 2, close[0] + 30, close[3] - 13, (235, 250, 251, 255), 2)
    active_context, _active_kind = frequency_band_context(freq_khz, mode)
    for preset, box in boxes["cells"]:
        label, _target_khz, kind = preset
        is_active = label.replace(" H", "") in active_context
        if kind == "broadcast":
            fill = (57, 40, 13, 235) if is_active else (38, 30, 17, 220)
            edge, accent = (237, 180, 75, 228), (247, 203, 125)
            group = "BROADCAST"
        else:
            fill = (12, 51, 68, 236) if is_active else (13, 31, 42, 222)
            edge, accent = (75, 205, 234, 225), (162, 232, 247)
            group = "HAM"
        bx0, by0, bx1, by1 = box
        draw_logical_rect(bx0, by0, bx1, by1, fill)
        for ax0, ay0, ax1, ay1 in ((bx0, by0, bx1, by0), (bx0, by1, bx1, by1), (bx0, by0, bx0, by1), (bx1, by0, bx1, by1)):
            draw_logical_line(ax0, ay0, ax1, ay1, edge if is_active else (*edge[:3], 105), 1)
        if is_active:
            draw_logical_line(bx0 + 12, by1 - 5, bx1 - 12, by1 - 5, edge, 2)
        draw_text(text_cache, (bx0 + bx1) / 2, (by0 + by1) / 2 - 8, label, accent, 20, True, False, "cm", family="Liberation Sans")
        draw_text(text_cache, (bx0 + bx1) / 2, by1 - 13, group, (*accent[:3], 190), 11, True, False, "cm", family="Liberation Sans")


def compact_font_review_boxes():
    """Temporary opaque rail workspace for evaluating compact VFO typefaces."""
    x0, x1 = LCD_NAV_X0 + 8, LOGICAL_W - 8
    y0 = 99
    y1 = lcd_nav_top(len(MENU_ITEMS)) - 8
    gap = 8
    half = (x1 - x0 - gap) / 2
    return {
        "panel": (LCD_NAV_X0, y0, LOGICAL_W, y1),
        "previous": (x0, y0 + 58, x0 + half, y0 + 124),
        "next": (x0 + half + gap, y0 + 58, x1, y0 + 124),
        "like": (x0, y0 + 138, x0 + half, y0 + 204),
        "delete": (x0 + half + gap, y0 + 138, x1, y0 + 204),
        "use": (x0, y0 + 218, x1, y0 + 274),
        "exit": (x0, y1 - 64, x1, y1 - 10),
    }


def compact_font_review_action_at(x, y):
    for action, box in compact_font_review_boxes().items():
        if action != "panel" and contains(box, x, y):
            return action
    return None


def draw_compact_font_review(text_cache, family, index, families, liked_fonts, active_family):
    """Opaque temporary controls so font testing never competes with Home UI."""
    boxes = compact_font_review_boxes()
    x0, y0, x1, y1 = boxes["panel"]
    draw_logical_rect(x0, y0, x1, y1, (5, 13, 18, 255))
    draw_logical_line(x0, y0, x1, y0, (100, 149, 155, 178), 1)
    draw_text(text_cache, x0 + 16, y0 + 20, "FONT REVIEW", (215, 231, 234), 15, True, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x1 - 16, y0 + 20, f"{index + 1}/{len(families)}", (127, 169, 175), 14, True, False, "rm", family="Liberation Sans")
    draw_text(text_cache, (x0 + x1) / 2, y0 + 42, family.upper(), (170, 198, 202), 16, True, False, "cm", family="Liberation Sans")

    def button(box, label, active=False, destructive=False):
        bx0, by0, bx1, by1 = box
        fill = (24, 67, 49, 255) if active else ((61, 25, 26, 255) if destructive else (17, 32, 40, 255))
        edge = (112, 234, 176, 228) if active else ((228, 112, 106, 198) if destructive else (103, 141, 149, 172))
        draw_logical_rect(bx0, by0, bx1, by1, fill)
        draw_logical_line(bx0, by0, bx1, by0, edge, 1)
        draw_logical_line(bx0, by1, bx1, by1, edge, 1)
        draw_logical_line(bx0, by0, bx0, by1, edge, 1)
        draw_logical_line(bx1, by0, bx1, by1, edge, 1)
        draw_text(text_cache, (bx0 + bx1) / 2, (by0 + by1) / 2, label, (238, 246, 247), 20, True, False, "cm", family="Liberation Sans")

    button(boxes["previous"], "<")
    button(boxes["next"], ">")
    button(boxes["like"], "LIKED" if family in liked_fonts else "LIKE", family in liked_fonts)
    button(boxes["delete"], "DELETE", destructive=True)
    button(boxes["use"], "USING" if family == active_family else "USE", family == active_family)
    button(boxes["exit"], "BACK TO HOME")


def lcd_home_volume_box(show_compact_readouts=True):
    """Persistent Home volume instrument in the calm upper right-rail gap."""
    x0, x1 = LCD_NAV_X0 + 10, LOGICAL_W - 10
    _pass_x0, _pass_y0, _pass_x1, pass_y1 = lcd_home_bandwidth_box(show_compact_readouts)
    y0 = pass_y1 + 10
    y1 = min(lcd_nav_top(len(MENU_ITEMS)) - 18, y0 + 72)
    return x0, y0, x1, max(y0 + 46, y1)


def lcd_home_volume_mute_box(show_compact_readouts=True):
    """Compact speaker toggle at the left of the Home slider line."""
    x0, _y0, _x1, y1 = lcd_home_volume_box(show_compact_readouts)
    return x0 + 6, y1 - 39, x0 + 46, y1 - 5


def lcd_home_volume_track_box(show_compact_readouts=True):
    """The actual finger range excludes the separate speaker toggle."""
    x0, _y0, x1, y1 = lcd_home_volume_box(show_compact_readouts)
    return x0 + 56, y1 - 32, x1 - 12, y1 - 8


def home_volume_at_x(x, show_compact_readouts=True):
    return volume_at_x(x, lcd_home_volume_track_box(show_compact_readouts))


def lcd_home_smeter_box(show_compact_readouts=True):
    """Compact RF meter below Home volume and above the tile grid."""
    x0, _volume_y0, x1, volume_y1 = lcd_home_volume_box(show_compact_readouts)
    y0 = volume_y1 + 10
    y1 = min(lcd_nav_top() - 16, y0 + 76)
    return x0, y0, x1, max(y0 + 48, y1)


def lcd_home_bandwidth_box(show_compact_readouts=True):
    """Dedicated Home-rail passband instrument beneath the mode cluster."""
    x0, x1 = LCD_NAV_X0 + 10, LOGICAL_W - 10
    # The compressed mode cells need a real quiet strip below them. Without
    # it the passband heading visually runs into the lower annunciator row.
    # Preserve the established passband position after lowering the modes.
    y0 = lcd_home_mode_grid_bottom(show_compact_readouts) + 20
    return x0, y0, x1, y0 + LCD_HOME_PASSBAND_HEIGHT


def lcd_nav_box(index, item_count=None):
    """Return the logical box for the permanent LCD navigation rail."""
    col = index % 2
    row = index // 2
    grid_width = 2 * LCD_NAV_TILE_W + LCD_NAV_GAP
    x0 = LCD_NAV_X0 + (LOGICAL_W - LCD_NAV_X0 - grid_width) / 2 + col * (LCD_NAV_TILE_W + LCD_NAV_GAP)
    y0 = lcd_nav_top(item_count) + row * (LCD_NAV_TILE_H + LCD_NAV_GAP)
    return x0, y0, x0 + LCD_NAV_TILE_W, y0 + LCD_NAV_TILE_H


def lcd_nav_items(settings_open=False, digital_open=False):
    """Return the active Home-rail level, with DIGI owning WSPR tools."""
    if digital_open:
        return DIGITAL_MENU_ITEMS
    return SETTINGS_MENU_ITEMS if settings_open else MENU_ITEMS


def lcd_nav_item_at(x, y, items=MENU_ITEMS):
    if not LCD_800_MODE:
        return None
    for index in range(len(items)):
        if contains(lcd_nav_box(index, len(items)), x, y):
            return index
    return None


def lcd_nav_tile_background(text_cache):
    """Return the lightly rounded shared Home-tile background texture."""
    key = "lcd_nav_tile_background_v3_compact"
    cached = text_cache.cache.get(("surface", key))
    if cached is not None:
        return cached
    scale = 2
    width, height = LCD_NAV_TILE_W * scale, LCD_NAV_TILE_H * scale
    surface = pygame.Surface((width, height), pygame.SRCALPHA)
    rect = pygame.Rect(0, 0, width, height)
    radius = 10 * scale
    pygame.draw.rect(surface, (17, 29, 38, 218), rect, border_radius=radius)
    # One restrained outline preserves the instrument-panel treatment while
    # rounding the formerly abrupt corners just enough for a touch UI.
    pygame.draw.rect(surface, (86, 111, 122, 182), rect, width=scale, border_radius=radius)
    pygame.draw.line(surface, (142, 164, 173, 116), (radius, 1), (width - radius, 1), scale)
    pygame.draw.line(surface, (30, 49, 59, 188), (radius, height - 1), (width - radius, height - 1), scale)
    return text_cache.surface_texture(key, surface)


def draw_lcd_home_volume_slider(text_cache, volume, muted=False, show_compact_readouts=True):
    """Draw the master slider and its compact, independent mute switch."""
    x0, y0, x1, y1 = lcd_home_volume_box(show_compact_readouts)
    level = clamp(volume if volume is not None else 0.0, 0.0, 1.0)
    mute_x0, mute_y0, mute_x1, mute_y1 = lcd_home_volume_mute_box(show_compact_readouts)
    status = "MUTE" if muted else main_volume_label(level)
    status_color = MUTE_ACCENT if muted or level <= MAIN_VOLUME_MUTE_THRESHOLD else (239, 247, 248)
    draw_logical_rect(x0, y0, x1, y1, (11, 20, 27, 228))
    draw_logical_line(x0, y0, x1, y0, (112, 136, 146, 125), 1)
    draw_logical_line(x0, y1, x1, y1, (25, 42, 51, 210), 1)
    draw_text(text_cache, x0 + 12, y0 + 9, "VOLUME", (170, 201, 207), 15, True, False, "lt", family="Liberation Sans")
    draw_text(text_cache, x1 - 12, y0 + 13, status, status_color, 18, True, False, "rt", family="Liberation Sans")
    button_fill = (76, 23, 32, 238) if muted else (18, 38, 49, 238)
    button_edge = MUTE_ACCENT_ALPHA if muted else (91, 186, 204, 188)
    icon_color = (*MUTE_ACCENT, 255) if muted else (145, 231, 242, 255)
    draw_logical_rect(mute_x0, mute_y0, mute_x1, mute_y1, button_fill)
    draw_logical_line(mute_x0, mute_y0, mute_x1, mute_y0, button_edge, 1)
    draw_logical_line(mute_x0, mute_y1, mute_x1, mute_y1, button_edge, 1)
    draw_logical_line(mute_x0, mute_y0, mute_x0, mute_y1, button_edge, 1)
    draw_logical_line(mute_x1, mute_y0, mute_x1, mute_y1, button_edge, 1)
    cx, cy = (mute_x0 + mute_x1) / 2, (mute_y0 + mute_y1) / 2
    draw_logical_rect(cx - 13, cy - 5, cx - 6, cy + 5, icon_color)
    draw_logical_polyline(((cx - 6, cy - 5), (cx + 5, cy - 13), (cx + 5, cy + 13), (cx - 6, cy + 5)), icon_color, 2.5)
    if muted:
        draw_logical_line(cx - 16, cy - 14, cx + 16, cy + 14, icon_color, 3)
    track_x0, track_y0, track_x1, track_y1 = lcd_home_volume_track_box(show_compact_readouts)
    track_y = (track_y0 + track_y1) / 2
    draw_logical_rect(track_x0, track_y - SLIDER_STEM_HALF_HEIGHT, track_x1, track_y + SLIDER_STEM_HALF_HEIGHT, (20, 34, 42, 235))
    draw_logical_rect(track_x0, track_y - SLIDER_STEM_HALF_HEIGHT, track_x0 + (track_x1 - track_x0) * level, track_y + SLIDER_STEM_HALF_HEIGHT, (67, 205, 149, 230))
    knob_x = track_x0 + (track_x1 - track_x0) * level
    draw_logical_rect(knob_x - 6, track_y - 12, knob_x + 6, track_y + 12, (233, 247, 248, 255))


def compact_smeter_label(dbm):
    """Translate the calibrated reading into the familiar short S label."""
    if dbm is None:
        return "S?"
    if dbm < SMETER_S9_DBM:
        fraction = clamp((dbm - SMETER_FLOOR_DBM) / (SMETER_S9_DBM - SMETER_FLOOR_DBM), 0.0, 1.0)
        return f"S{max(1, min(9, round(1 + fraction * 8)))}"
    if dbm < SMETER_PLUS20_DBM:
        return f"S9+{round(dbm - SMETER_S9_DBM):.0f}"
    return f"S9+{round(dbm - SMETER_S9_DBM):.0f}"


def draw_lcd_home_smeter(text_cache, smeter_dbm):
    """A small live, calibrated RF reading for the persistent Home rail."""
    x0, y0, x1, y1 = lcd_home_smeter_box()
    dbm = float(smeter_dbm) if isinstance(smeter_dbm, (int, float)) else SMETER_FLOOR_DBM
    live_segments = smeter_segment_position(dbm)
    draw_logical_rect(x0, y0, x1, y1, (9, 17, 23, 228))
    draw_logical_line(x0, y0, x1, y0, (97, 125, 136, 116), 1)
    draw_logical_line(x0, y1, x1, y1, (23, 40, 49, 210), 1)
    draw_text(text_cache, x0 + 12, y0 + 13, "S-METER", (170, 201, 207), 14, True, False, "lt", family="Liberation Sans")
    draw_text(text_cache, x1 - 12, y0 + 13, compact_smeter_label(dbm), (226, 244, 247), 17, True, False, "rt", family="Liberation Sans")
    draw_text(text_cache, x1 - 12, y0 + 30, f"{dbm:.0f} dBm", (142, 181, 191), 14, True, False, "rt", family="Liberation Sans")
    track_x0, track_x1 = x0 + 12, x1 - 12
    track_y = y0 + 47
    segment_w = (track_x1 - track_x0) / 36.0
    for index in range(36):
        sx0 = track_x0 + index * segment_w + 1
        sx1 = track_x0 + (index + 1) * segment_w - 1
        active = index + 0.5 <= live_segments
        red = index >= SMETER_S1_TO_S9_SEGMENTS + SMETER_S9_TO_PLUS20_SEGMENTS
        if active:
            color = (243, 105, 111, 242) if red else (83, 216, 248, 244)
        else:
            color = (75, 43, 48, 142) if red else (31, 62, 75, 160)
        draw_logical_rect(sx0, track_y - SMETER_COMPACT_BAR_HALF_HEIGHT, sx1, track_y + SMETER_COMPACT_BAR_HALF_HEIGHT, color)
    for label, position in (("S1", 0), ("S5", 11), ("S9", 22), ("+20", 28)):
        lx = track_x0 + (track_x1 - track_x0) * position / 36.0
        draw_text(text_cache, lx, y1 - 10, label, (138, 166, 176), 10, True, False, "cm", family="Liberation Sans")


def draw_lcd_home_bandwidth(text_cache, low_cut, high_cut, box=None, title="PASSBAND"):
    """Draw a 10 kHz ICOM-inspired, but more informative, passband meter."""
    x0, y0, x1, y1 = box or lcd_home_bandwidth_box()
    low_cut = float(low_cut if low_cut is not None else -1200.0)
    high_cut = float(high_cut if high_cut is not None else 1200.0)
    if high_cut < low_cut:
        low_cut, high_cut = high_cut, low_cut
    plot_x0, plot_x1 = x0 + 18, x1 - 18
    center_x = (plot_x0 + plot_x1) / 2
    plot_y = y1 - 28
    scale_hz = 5000.0
    def cut_x(cut_hz):
        return center_x + clamp(cut_hz / scale_hz, -1.0, 1.0) * (plot_x1 - plot_x0) / 2

    low_x, high_x = cut_x(low_cut), cut_x(high_cut)
    width_hz = max(0.0, high_cut - low_cut)
    fill = (42, 154, 176, 88)
    edge = (113, 234, 240, 238)
    grid = (87, 125, 138, 132)
    quiet = (153, 186, 195)
    draw_logical_rect(x0, y0, x1, y1, (7, 15, 21, 236))
    draw_logical_line(x0, y0, x1, y0, (82, 127, 141, 154), 1)
    draw_logical_line(x0, y1, x1, y1, (24, 46, 55, 220), 1)
    draw_text(text_cache, x0 + 11, y0 + 14, title, quiet, 13, True, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x1 - 11, y0 + 14, "10 kHz", (180, 214, 220), 13, True, False, "rm", family="Liberation Sans")
    # Delicate 1 kHz graduations make the scale useful without imitating the
    # crude single-outline ICOM glyph. The 0-Hz reference remains dominant.
    for index in range(-5, 6):
        x = center_x + index * (plot_x1 - plot_x0) / 10
        major = index in (-5, 0, 5)
        tick_h = 10 if major else 5
        draw_logical_line(x, plot_y, x, plot_y - tick_h, (grid[0], grid[1], grid[2], 206 if major else 126), 1 if not major else 1.5)
    draw_logical_line(plot_x0, plot_y, plot_x1, plot_y, (107, 151, 162, 188), 1)
    # Raise the trace from 23 to 29 logical pixels above its baseline: a
    # 25% taller passband silhouette without changing the panel or labels.
    top_y = y0 + 32
    shoulder_y = y0 + 38
    # Keep the sides almost vertical. Wide filters retain a slight analog
    # taper, while CW/narrow widths must not collapse into a camel-shaped
    # hump just because the graphical shoulders are wider than the passband.
    side_inset = min(1.5, max(0.25, (high_x - low_x) * 0.08))
    passband_points = (
        (low_x, plot_y),
        (low_x + side_inset, shoulder_y),
        (low_x + side_inset, top_y),
        (high_x - side_inset, top_y),
        (high_x - side_inset, shoulder_y),
        (high_x, plot_y),
    )
    draw_logical_area(passband_points, plot_y, fill)
    draw_logical_polyline(passband_points, edge, 1.8)
    draw_logical_line(center_x, top_y - 6, center_x, plot_y + 4, (238, 202, 96, 232), 1.5)
    for label, x in (("−5", plot_x0), ("0", center_x), ("+5", plot_x1)):
        draw_text(text_cache, x, y1 - 8, label, (137, 171, 181), 12, True, False, "cm", family="Liberation Sans")
    draw_text(
        text_cache,
        center_x,
        y0 + 21,
        f"{width_hz / 1000.0:.1f} kHz",
        (214, 240, 242),
        14,
        True,
        False,
        "cm",
        family="Liberation Sans",
    )


def lcd_filter_drawer_boxes():
    """Right-rail geometry for the non-modal LCD passband editor."""
    x0, x1 = LCD_NAV_X0, LOGICAL_W
    inner_x0, inner_x1 = x0 + 10, x1 - 10
    # Keep choice buttons bottom-aligned immediately above Back. That gives
    # the two continuous instruments generous, finger-friendly travel.
    preset_top, preset_h, preset_gap = 493, 50, 8
    preset_w = (inner_x1 - inner_x0 - 8) / 2
    preset_boxes = []
    for index, (name, width_hz) in enumerate(FILTER_WIDTH_PRESETS):
        col, row = index % 2, index // 2
        left = inner_x0 + col * (preset_w + 8)
        top = preset_top + row * (preset_h + preset_gap)
        preset_boxes.append((name, width_hz, (left, top, left + preset_w, top + preset_h)))
    return {
        "panel": (x0, LCD_DRAWER_HEADER_H, x1, lcd_rail_bottom()),
        "close": (inner_x0, lcd_rail_bottom() - 78, inner_x1, lcd_rail_bottom() - 10),
        "visual": (inner_x0, 108, inner_x1, 211),
        "shift": (inner_x0, 217, inner_x1, 329),
        "width": (inner_x0, 341, inner_x1, 441),
        "presets": tuple(preset_boxes),
    }


def lcd_filter_slider_track_box(box, lower_slop=0):
    """Only a rail and its immediate finger margin are interactive."""
    return box[0], box[3] - 34, box[2], box[3] + lower_slop


def next_lcd_filter_preset_width(name, current_width_hz, preset_width_hz):
    """Return the selected width, including the compact 9/12 kHz cycle."""
    if name == "WIDE 9/12k":
        return 12000 if abs(current_width_hz - 9000) <= FILTER_SNAP_HZ / 2 else 9000
    return preset_width_hz


def filter_shift_response_exponent(width_hz):
    """Return a fine-centre shift response for CW and narrow voice only."""
    return (
        FILTER_NARROW_SHIFT_RESPONSE_EXPONENT
        if width_hz <= FILTER_NARROW_SHIFT_MAX_HZ
        else 1.0
    )


def filter_shift_slider_fraction(center_hz, width_hz):
    """Map an actual passband center back to its curved slider position."""
    response = clamp(center_hz / FILTER_LIMIT_HZ, -1.0, 1.0)
    exponent = filter_shift_response_exponent(width_hz)
    if exponent != 1.0 and response:
        response = math.copysign(abs(response) ** (1.0 / exponent), response)
    return clamp((response + 1.0) / 2.0, 0.0, 1.0)


def filter_width_from_slider_fraction(fraction):
    """Progressive Width rail: precise at CW, faster through 6 kHz."""
    fraction = clamp(fraction, 0.0, 1.0)
    if fraction <= FILTER_WIDTH_FINE_TRACK_FRACTION:
        fine_fraction = fraction / FILTER_WIDTH_FINE_TRACK_FRACTION
        return FILTER_SNAP_HZ + (FILTER_WIDTH_FINE_TARGET_HZ - FILTER_SNAP_HZ) * (
            fine_fraction ** FILTER_WIDTH_FINE_RESPONSE_EXPONENT
        )
    upper_fraction = (fraction - FILTER_WIDTH_FINE_TRACK_FRACTION) / (1.0 - FILTER_WIDTH_FINE_TRACK_FRACTION)
    return FILTER_WIDTH_FINE_TARGET_HZ + (FILTER_LIMIT_HZ - FILTER_WIDTH_FINE_TARGET_HZ) * upper_fraction


def filter_width_slider_fraction(width_hz):
    """Inverse of the progressive Width rail, for faithful thumb placement."""
    width_hz = clamp(width_hz, FILTER_SNAP_HZ, FILTER_LIMIT_HZ)
    if width_hz <= FILTER_WIDTH_FINE_TARGET_HZ:
        fine_fraction = (width_hz - FILTER_SNAP_HZ) / max(1.0, FILTER_WIDTH_FINE_TARGET_HZ - FILTER_SNAP_HZ)
        return FILTER_WIDTH_FINE_TRACK_FRACTION * (fine_fraction ** (1.0 / FILTER_WIDTH_FINE_RESPONSE_EXPONENT))
    upper_fraction = (width_hz - FILTER_WIDTH_FINE_TARGET_HZ) / max(1.0, FILTER_LIMIT_HZ - FILTER_WIDTH_FINE_TARGET_HZ)
    return FILTER_WIDTH_FINE_TRACK_FRACTION + (1.0 - FILTER_WIDTH_FINE_TRACK_FRACTION) * upper_fraction


def draw_lcd_filter_shift_slider(text_cache, box, low_cut, high_cut):
    x0, y0, x1, y1 = box
    center_hz = (low_cut + high_cut) / 2.0
    # Fixed ±12 kHz position scale: changing Width must not make the Shift
    # thumb appear to slide when its actual center frequency is unchanged.
    fraction = filter_shift_slider_fraction(center_hz, high_cut - low_cut)
    track_x0, track_x1 = x0 + 10, x1 - 10
    track_y = y1 - 14
    label_y = track_y - 27
    knob_x = track_x0 + (track_x1 - track_x0) * fraction
    shift_label = "CENTER LOCK" if abs(center_hz) < FILTER_SNAP_HZ else format_filter_cut(center_hz)
    draw_text(text_cache, x0 + 10, label_y, "SHIFT", (221, 241, 243), 15, True, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x1 - 10, label_y, shift_label, (113, 236, 190), 17, True, False, "rm", family="Liberation Sans")
    draw_logical_rect(track_x0, track_y - SLIDER_STEM_HALF_HEIGHT, track_x1, track_y + SLIDER_STEM_HALF_HEIGHT, (22, 39, 47, 248))
    zero_x = (track_x0 + track_x1) / 2
    draw_logical_line(zero_x, track_y - 16, zero_x, track_y + 16, (241, 193, 82, 248), 2)
    draw_logical_line(track_x0, track_y - 7, track_x0, track_y + 7, (77, 126, 139, 188), 1)
    draw_logical_line(track_x1, track_y - 7, track_x1, track_y + 7, (77, 126, 139, 188), 1)
    draw_logical_rect(min(zero_x, knob_x), track_y - SLIDER_STEM_HALF_HEIGHT, max(zero_x, knob_x), track_y + SLIDER_STEM_HALF_HEIGHT, (76, 214, 170, 184))
    draw_logical_rect(knob_x - 6, track_y - 11, knob_x + 6, track_y + 11, (231, 247, 247, 255))


def draw_lcd_filter_width_slider(text_cache, box, low_cut, high_cut):
    x0, y0, x1, y1 = box
    width_hz = clamp(high_cut - low_cut, FILTER_SNAP_HZ, FILTER_LIMIT_HZ)
    fraction = filter_width_slider_fraction(width_hz)
    track_x0, track_x1 = x0 + 10, x1 - 10
    track_y = y1 - 14
    label_y = track_y - 27
    knob_x = track_x0 + (track_x1 - track_x0) * fraction
    draw_text(text_cache, x0 + 10, label_y, "WIDTH", (221, 241, 243), 15, True, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x1 - 10, label_y, format_filter_width(width_hz), (110, 222, 242), 17, True, False, "rm", family="Liberation Sans")
    draw_logical_rect(track_x0, track_y - SLIDER_STEM_HALF_HEIGHT, track_x1, track_y + SLIDER_STEM_HALF_HEIGHT, (22, 39, 47, 248))
    draw_logical_rect(track_x0, track_y - SLIDER_STEM_HALF_HEIGHT, knob_x, track_y + SLIDER_STEM_HALF_HEIGHT, (84, 188, 226, 184))
    for fraction_mark in (0.0, 0.25, 0.5, 0.75, 1.0):
        mark_x = track_x0 + (track_x1 - track_x0) * fraction_mark
        draw_logical_line(mark_x, track_y - 7, mark_x, track_y + 7, (98, 154, 170, 156), 1)
    draw_logical_rect(knob_x - 6, track_y - 11, knob_x + 6, track_y + 11, (231, 247, 247, 255))


def draw_lcd_filter_drawer(text_cache, mode, low_cut, high_cut):
    """Touch-safe passband control drawer that leaves the waterfall live."""
    boxes = lcd_filter_drawer_boxes()
    x0, y0, x1, y1 = boxes["panel"]
    width_hz = high_cut - low_cut
    # This drawer is an independent operating surface. It must be fully
    # opaque so the inactive Home/mode controls beneath cannot be mistaken
    # for live controls or overlap the slider labels.
    draw_logical_rect(x0, y0, x1, y1, (6, 13, 19, 255))
    draw_radio_close_button(text_cache, boxes["close"])
    draw_lcd_drawer_heading(text_cache, x0 + 12, 88, "PASSBAND")
    draw_lcd_home_bandwidth(text_cache, low_cut, high_cut, box=boxes["visual"], title=f"LIVE  {mode.upper()}")
    draw_lcd_filter_shift_slider(text_cache, boxes["shift"], low_cut, high_cut)
    draw_lcd_filter_width_slider(text_cache, boxes["width"], low_cut, high_cut)
    draw_text(text_cache, x0 + 12, 475, "WIDTH PRESETS", (169, 203, 208), 13, True, False, "lm", family="Liberation Sans")
    current_preset = filter_preset_index(width_hz)
    for index, (name, preset_width_hz, box) in enumerate(boxes["presets"]):
        active = current_preset == index or (
            name == "WIDE 9/12k" and abs(width_hz - 12000) <= FILTER_SNAP_HZ / 2
        )
        draw_lcd_audio_tile(
            text_cache,
            box,
            name.replace("VOICE ", ""),
            ("9 / 12 kHz" if name == "WIDE 9/12k" else format_filter_width(preset_width_hz)),
            active,
            accent=(104, 234, 180, 228),
            title_size=13,
            detail_size=13,
        )


def draw_lcd_navigation(text_cache, volume=None, smeter_dbm=None, muted=False, settings_open=False,
                        digital_open=False, low_cut=None, high_cut=None, instrument_layout="expanded"):
    """Draw the 256 px right rail shared by the LCD and Mac simulator."""
    if not LCD_800_MODE:
        return
    rail_bottom = lcd_rail_bottom()
    # The RF lower-status bar ends at x=1024.  The remaining Home rail is one
    # uninterrupted black panel from the VFO to the physical bottom edge.
    draw_logical_rect(LCD_NAV_X0, 0, LOGICAL_W, rail_bottom, (3, 6, 9, 255))
    draw_logical_line(LCD_NAV_X0, 0, LCD_NAV_X0, rail_bottom, (125, 147, 158, 118), 1)
    items = lcd_nav_items(settings_open, digital_open)
    if not settings_open and not digital_open:
        show_compact_readouts = instrument_layout == "compact"
        draw_lcd_home_bandwidth(
            text_cache, low_cut, high_cut,
            box=lcd_home_bandwidth_box(show_compact_readouts),
        )
        draw_lcd_home_volume_slider(
            text_cache, volume, muted,
            show_compact_readouts=show_compact_readouts,
        )
    for index, (kind, label) in enumerate(items):
        bx0, by0, bx1, by1 = lcd_nav_box(index, len(items))
        tile_tex, _tile_w, _tile_h = lcd_nav_tile_background(text_cache)
        draw_textured_quad(tile_tex, bx0, by0, bx1, by1, 0, 0, 1, 1)
        tex, _tex_w, _tex_h = menu_icon_texture(
            text_cache, kind, label, LCD_NAV_TILE_W - 8, LCD_NAV_TILE_H - 8
        )
        draw_textured_quad(tex, bx0 + 4, by0 + 4, bx1 - 4, by1 - 4, 0, 0, 1, 1, 0.96)


def draw_lcd_mode_annunciators(text_cache, mode, digital, freq_khz, smeter_dbm=None,
                               show_compact_readouts=True,
                               compact_frequency_font_family=COMPACT_FREQUENCY_FONT_FAMILY):
    """Show Home-rail modes, optionally with the compact VFO instruments."""
    x0, y0, x1, y1 = LCD_ANNUNCIATOR_BOX
    # The main frequency display remains untouched. This smaller right-rail
    # readout stays visually open: it is a live value, not a second button.
    exact_mode = mode.upper()
    active_mode = KIWI_MODE_FAMILY.get(exact_mode, exact_mode)
    layout_key = "compact" if show_compact_readouts else "expanded"
    cache_key = ("surface", f"lcd_annunciator_radio_v9_compact_{layout_key}_{active_mode}_{digital.upper()}")
    cached = text_cache.cache.get(cache_key)
    if cached is None:
        width, height, scale = int(x1 - x0), int(y1 - y0), 2
        surface = pygame.Surface((width * scale, height * scale), pygame.SRCALPHA)

        def pixel(value):
            return int(round(value * scale))

        def rounded(left, top, right, bottom, fill, edge=None, radius=5):
            rect = pygame.Rect(pixel(left), pixel(top), pixel(right - left), pixel(bottom - top))
            pygame.draw.rect(surface, fill, rect, border_radius=pixel(radius))
            if edge is not None:
                pygame.draw.rect(surface, edge, rect, width=pixel(1), border_radius=pixel(radius))

        surface.fill((3, 6, 9, 232))
        grid_y0, cell_h, gap = lcd_home_mode_grid_geometry(show_compact_readouts)
        grid_w = (width - 12) * 0.85
        grid_x0 = (width - grid_w) / 2
        cell_w = (grid_w - 3 * gap) / 4
        for index, label in enumerate(DESKTOP_1280_MODE_ANNUNCIATORS):
            col, row = index % 4, index // 4
            left = grid_x0 + col * (cell_w + gap)
            top = grid_y0 + row * (cell_h + gap)
            # Keep the grid cells neutral. The active state is drawn later as
            # a compact pill tight to the mode label, not a full blue tile.
            rounded(
                left,
                top,
                left + cell_w,
                top + cell_h,
                (7, 10, 13, 238),
                (62, 67, 73, 228),
                5,
            )
        surface = pygame.transform.smoothscale(surface, (width, height))
        cached = text_cache.surface_texture(cache_key[1], surface)
    texture, texture_w, texture_h = cached
    draw_textured_quad(texture, x0, y0, x0 + texture_w, y0 + texture_h, 0, 0, 1, 1)

    if show_compact_readouts:
        # Compact mode makes this the primary frequency readout. The SDR is
        # frequency-centric, so do not waste this narrow rail on a repeated
        # MHz unit: give the digits the entire available width instead.
        frequency_text = sdr_ui.format_freq(freq_khz)
        frequency_left_margin = 8
        frequency_right_margin = 8
        frequency_size = 60
        fit_target = "30.000.000"
        frequency_width_limit = (x1 - frequency_right_margin) - (x0 + frequency_left_margin)
        # The compact rail is a secondary instrument lane. Keep its enlarged
        # digits calm in neutral gray rather than competing with the primary
        # green VFO readout across the display.
        frequency_color = (161, 169, 172)
        frequency_source_width = max(
            text_cache.font(frequency_size, bold=True, family=compact_frequency_font_family).size(frequency_text)[0],
            text_cache.font(frequency_size, bold=True, family=compact_frequency_font_family).size(fit_target)[0],
        )
        frequency_x_scale = min(1.0, frequency_width_limit / max(1, frequency_source_width))
        frequency_right = x1 - frequency_right_margin
        draw_text_scaled_x(
            text_cache, frequency_right, y0 + 53, frequency_text, frequency_color, frequency_size,
            frequency_x_scale, bold=True, anchor="rm", family=compact_frequency_font_family,
        )
        # This narrow, persistent context line answers the basic operating
        # question at a glance and doubles as the entry point to the large
        # band navigator. It deliberately sits outside the frequency tap box.
        draw_band_context_chip(
            text_cache, compact_band_context_touch_box(), freq_khz, mode, compact=True
        )

        # Give the Home meter enough physical weight to read as an instrument,
        # rather than a thin status decoration beside the VFO.
        # Reserve quiet air around the meter so it reads as its own small
        # instrument rather than touching either the band tag or mode grid.
        meter_x0, meter_y0, meter_x1, meter_y1 = x0 + 6, y0 + 108, x1 - 6, y0 + 178
        meter_value = float(smeter_dbm) if isinstance(smeter_dbm, (int, float)) else SMETER_FLOOR_DBM
        meter_level = smeter_segment_position(meter_value)
        draw_logical_rect(meter_x0, meter_y0, meter_x1, meter_y1, (7, 15, 21, 218))
        draw_logical_line(meter_x0, meter_y0, meter_x1, meter_y0, (72, 101, 112, 142), 1)
        draw_text(text_cache, meter_x0 + 9, meter_y0 + 12, "S-METER", (165, 199, 207), 13, True, False, "lm", family="Liberation Sans")
        draw_text(text_cache, meter_x1 - 9, meter_y0 + 14, f"{meter_value:.0f} dBm", (190, 218, 223), 17, True, False, "rm", family="Liberation Sans")
        meter_track_x0, meter_track_x1 = meter_x0 + 8, meter_x1 - 8
        meter_track_y = meter_y0 + 37
        segment_w = (meter_track_x1 - meter_track_x0) / 36
        for index in range(36):
            sx0 = meter_track_x0 + index * segment_w + 1
            sx1 = meter_track_x0 + (index + 1) * segment_w - 1
            active = index + 0.5 <= meter_level
            color = (92, 221, 231, 238) if index < 28 else (244, 104, 90, 238)
            draw_logical_rect(
                sx0,
                meter_track_y - SMETER_HOME_RAIL_BAR_HALF_HEIGHT,
                sx1,
                meter_track_y + SMETER_HOME_RAIL_BAR_HALF_HEIGHT,
                color if active else (31, 52, 61, 208),
            )
        for label, position in (("S1", 0), ("S3", 7), ("S5", 14), ("S7", 21), ("S9", 28), ("+20", 34)):
            lx = meter_track_x0 + (meter_track_x1 - meter_track_x0) * position / 36.0
            color = (236, 105, 109) if label in ("S9", "+20") else (151, 183, 191)
            draw_text(text_cache, lx, meter_y1 - 8, label, color, 12, True, False, "cm", family="Liberation Sans")

    grid_y0, cell_h, gap = lcd_home_mode_grid_geometry(show_compact_readouts)
    grid_w = (x1 - x0 - 12) * 0.85
    grid_x0 = x0 + ((x1 - x0) - grid_w) / 2
    cell_w = (grid_w - 3 * gap) / 4
    for index, label in enumerate(DESKTOP_1280_MODE_ANNUNCIATORS):
        col, row = index % 4, index // 4
        bx0 = grid_x0 + col * (cell_w + gap)
        bx1 = bx0 + cell_w
        by0 = y0 + grid_y0 + row * (cell_h + gap)
        by1 = by0 + cell_h
        active = mode_annunciator_active(label, active_mode, digital)
        if active:
            label_w, label_h = text_cache.font(14, bold=True, family="Liberation Sans").size(label)
            pill_pad_x, pill_pad_y = 7, 3
            pill_x0 = max(bx0 + 4, (bx0 + bx1 - label_w) / 2 - pill_pad_x)
            pill_x1 = min(bx1 - 4, (bx0 + bx1 + label_w) / 2 + pill_pad_x)
            pill_y0 = (by0 + by1 - label_h) / 2 - pill_pad_y
            pill_y1 = (by0 + by1 + label_h) / 2 + pill_pad_y
            draw_logical_rect(pill_x0, pill_y0, pill_x1, pill_y1, (39, 114, 218, 248))
            draw_logical_line(pill_x0, pill_y0, pill_x1, pill_y0, (105, 176, 250, 255), 1)
            draw_logical_line(pill_x0, pill_y1, pill_x1, pill_y1, (20, 74, 159, 255), 1)
        draw_text(text_cache, (bx0 + bx1) / 2, (by0 + by1) / 2, label,
                  (246, 248, 250) if active else (205, 211, 215), 14, True, False, "cm",
                  family="Liberation Sans")


def draw_picker_button(text_cache, box, label, size=16, selected=False):
    x0, y0, x1, y1 = box
    fill = (72, 77, 81, 255) if selected else (38, 42, 46, 255)
    outline = (220, 223, 225, 235) if selected else (150, 155, 159, 220)
    draw_logical_rect(x0, y0, x1, y1, fill)
    draw_logical_line(x0, y0, x1, y0, outline, 1)
    draw_logical_line(x0, y1, x1, y1, outline, 1)
    draw_logical_line(x0, y0, x0, y1, outline, 1)
    draw_logical_line(x1, y0, x1, y1, outline, 1)
    draw_text(text_cache, (x0 + x1) / 2, (y0 + y1) / 2, label, (238, 240, 242), size, True, False, "cm")


def deepgram_keyboard_rows(mode):
    if mode == "digits":
        return DEEPGRAM_KEY_DIGIT_ROWS
    if mode == "lower":
        return tuple((keys.lower(), x0, y0, key_w) for keys, x0, y0, key_w in DEEPGRAM_KEY_ROWS)
    return DEEPGRAM_KEY_ROWS


def deepgram_key_at(x, y, mode):
    for keys, x0, y0, key_w in deepgram_keyboard_rows(mode):
        if y0 <= y < y0 + 52 and x0 <= x < x0 + len(keys) * key_w:
            key = keys[min(len(keys) - 1, int((x - x0) // key_w))]
            return "BACK" if key == "<" else key
    return None


def deepgram_setup_action_at(x, y, mode):
    if DESKTOP_MODE and contains(DEEPGRAM_KEY_FIELD_BOX, x, y):
        return "PASTE"
    if contains(DEEPGRAM_KEY_MODE_BOX, x, y):
        return "MODE"
    if contains(DEEPGRAM_KEY_CLEAR_BOX, x, y):
        return "CLEAR"
    if contains(DEEPGRAM_KEY_CANCEL_BOX, x, y):
        return "CANCEL"
    if contains(DEEPGRAM_KEY_SAVE_BOX, x, y):
        return "SAVE"
    return deepgram_key_at(x, y, mode)


def draw_deepgram_setup(text_cache, value, mode, error=""):
    """A full-size, touch-safe secret-entry sheet above the live waterfall."""
    x0, y0, x1, y1 = DEEPGRAM_SETUP_BOX
    draw_logical_rect(0, 0, LOGICAL_W, LOGICAL_H, (2, 7, 11, 136))
    draw_logical_rect(x0, y0, x1, y1, (8, 18, 24, 244))
    draw_logical_line(x0, y0, x1, y0, (103, 215, 210, 188), 1)
    draw_text(text_cache, x0 + 30, y0 + 23, "DEEPGRAM API KEY", (224, 241, 243), 20, True, False, "lm", family="Cantarell")
    draw_text(text_cache, x1 - 28, y0 + 23, "LOCAL ONLY", (116, 184, 183), 13, False, False, "rm", family="Cantarell")
    field_color = (48, 75, 80, 246) if not error else (90, 47, 42, 246)
    draw_logical_rect(*DEEPGRAM_KEY_FIELD_BOX, field_color)
    draw_logical_line(DEEPGRAM_KEY_FIELD_BOX[0], DEEPGRAM_KEY_FIELD_BOX[1], DEEPGRAM_KEY_FIELD_BOX[2], DEEPGRAM_KEY_FIELD_BOX[1], (132, 190, 190, 184), 1)
    masked = "*" * len(value)
    field_text = masked or (
        "Click here or Cmd+V to paste your key"
        if DESKTOP_MODE
        else "Touch keys to enter your key"
    )
    field_color = (229, 241, 243) if value else (145, 171, 174)
    draw_text(text_cache, DEEPGRAM_KEY_FIELD_BOX[0] + 14, (DEEPGRAM_KEY_FIELD_BOX[1] + DEEPGRAM_KEY_FIELD_BOX[3]) / 2, field_text, field_color, 19, False, False, "lm", family="Cantarell")
    mode_label = "aA" if mode == "lower" else ("AA" if mode == "upper" else "123")
    draw_picker_button(text_cache, DEEPGRAM_KEY_MODE_BOX, mode_label, 15, mode != "lower")
    draw_picker_button(text_cache, DEEPGRAM_KEY_CLEAR_BOX, "CLR", 15)
    draw_picker_button(text_cache, DEEPGRAM_KEY_CANCEL_BOX, "X", 22)
    draw_picker_button(text_cache, DEEPGRAM_KEY_SAVE_BOX, "OK", 15, bool(value))
    for keys, row_x0, row_y0, key_w in deepgram_keyboard_rows(mode):
        for index, key in enumerate(keys):
            box = (row_x0 + index * key_w, row_y0, row_x0 + (index + 1) * key_w - 5, row_y0 + 52)
            draw_picker_button(text_cache, box, "BACK" if key == "<" else key, 16 if key == "<" else 22)
    message = error or (
        "Cmd+V pastes from the Mac clipboard. The key is never shown again."
        if DESKTOP_MODE
        else "Saved only on this device. The key is never shown again."
    )
    draw_text(text_cache, x0 + 30, y1 - 18, message, (246, 163, 116) if error else (124, 184, 187), 14, False, False, "lm", family="Cantarell")


def network_panel_boxes():
    """Large, touch-safe Network Manager layout for the 1280x800 display."""
    panel = (28, 32, LOGICAL_W - 28, LOGICAL_H - 28)
    x0, y0, x1, y1 = panel
    return {
        "panel": panel,
        "back": (x1 - 156, y0 + 16, x1 - 20, y0 + 72),
        "rescan": (x0 + 20, y1 - 72, x0 + 192, y1 - 16),
        "join": (x0 + 208, y1 - 72, x0 + 380, y1 - 16),
        "ethernet": (x0 + 20, y0 + 110, x0 + 434, y0 + 250),
        "wifi": (x0 + 20, y0 + 272, x0 + 434, y0 + 430),
        "list": (x0 + 462, y0 + 110, x1 - 20, y1 - 92),
    }


def network_scan_boxes(networks):
    list_box = network_panel_boxes()["list"]
    x0, y0, x1, y1 = list_box
    columns, gap, row_h = 2, 14, 72
    width = (x1 - x0 - gap) / columns
    boxes = []
    for index, _network in enumerate(networks[:10]):
        col, row = index % columns, index // columns
        bx0 = x0 + col * (width + gap)
        by0 = y0 + 44 + row * (row_h + 10)
        boxes.append((bx0, by0, bx0 + width, by0 + row_h))
    return boxes


def network_password_boxes():
    panel = (166, 82, LOGICAL_W - 166, LOGICAL_H - 54)
    x0, y0, x1, y1 = panel
    field = (x0 + 26, y0 + 82, x1 - 26, y0 + 142)
    fx0, fy0, fx1, fy1 = field
    return {
        "panel": panel,
        "field": field,
        "reveal": (fx1 - 70, fy0 + 7, fx1 - 8, fy1 - 7),
        "mode": (x0 + 26, y0 + 160, x0 + 130, y0 + 216),
        "caps": (x0 + 146, y0 + 160, x0 + 250, y0 + 216),
        "clear": (x0 + 266, y0 + 160, x0 + 370, y0 + 216),
        "cancel": (x1 - 254, y0 + 160, x1 - 146, y0 + 216),
        "join": (x1 - 130, y0 + 160, x1 - 26, y0 + 216),
    }


def network_keyboard_rows(mode, caps=False):
    if mode == "symbols":
        labels = ("1234567890", "!@#$%&*_-+", "()[]{}.,/<")
    elif caps or mode == "upper":
        labels = ("QWERTYUIOP", "ASDFGHJKL", "ZXCVBNM<")
    else:
        labels = ("qwertyuiop", "asdfghjkl", "zxcvbnm<")
    panel = network_password_boxes()["panel"]
    x0, y0, x1, _y1 = panel
    rows = []
    for row, keys in enumerate(labels):
        key_w = min(70, (x1 - x0 - 52) / len(keys))
        row_w = len(keys) * key_w
        row_x0 = (x0 + x1 - row_w) / 2
        rows.append((keys, row_x0, y0 + 242 + row * 72, key_w))
    return rows


def network_password_key_at(x, y, mode, caps=False):
    for keys, x0, y0, key_w in network_keyboard_rows(mode, caps):
        if y0 <= y <= y0 + 58 and x0 <= x <= x0 + len(keys) * key_w:
            key = keys[min(len(keys) - 1, int((x - x0) // key_w))]
            return "BACK" if key == "<" else key
    return None


def draw_network_password_eye(box, revealed):
    """Draw a compact eye toggle that remains legible over the dark field."""
    x0, y0, x1, y1 = box
    color = (116, 238, 189, 245) if revealed else (171, 205, 209, 220)
    draw_logical_rect(x0, y0, x1, y1, (16, 50, 55, 238) if revealed else (10, 28, 35, 238))
    draw_logical_line(x0, y0, x1, y0, (*color[:3], 170), 1)
    draw_logical_line(x0, y1, x1, y1, (*color[:3], 120), 1)
    cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
    eye = ((cx - 20, cy), (cx - 10, cy - 9), (cx, cy - 12), (cx + 10, cy - 9), (cx + 20, cy),
           (cx + 10, cy + 9), (cx, cy + 12), (cx - 10, cy + 9), (cx - 20, cy))
    draw_logical_polyline(eye, color, 1.7)
    draw_logical_circle(cx, cy, 4.2, color, 18, True)
    if revealed:
        draw_logical_line(cx - 22, cy + 14, cx + 22, cy - 14, (225, 241, 243, 235), 2)


def network_status_text(device):
    state = str(device.get("state", "unavailable")).upper()
    address = next(iter(device.get("addresses") or ()), "NO IP")
    connection = str(device.get("connection") or "NOT CONNECTED")
    return state, connection, address


def draw_network_status_card(text_cache, box, label, device, preferred):
    x0, y0, x1, y1 = box
    state, connection, address = network_status_text(device or {})
    active = state == "CONNECTED"
    edge = (83, 229, 165, 220) if active else (117, 140, 151, 110)
    fill = (10, 35, 34, 236) if active else (13, 23, 30, 232)
    draw_logical_rect(x0, y0, x1, y1, fill)
    for ax0, ay0, ax1, ay1 in ((x0, y0, x1, y0), (x0, y1, x1, y1), (x0, y0, x0, y1), (x1, y0, x1, y1)):
        draw_logical_line(ax0, ay0, ax1, ay1, edge, 1)
    draw_text(text_cache, x0 + 20, y0 + 24, label, (225, 241, 243), 21, True, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x1 - 20, y0 + 24, "PRIMARY" if preferred else "STANDBY", (105, 238, 177) if active else (143, 169, 173), 14, True, False, "rm", family="Liberation Sans")
    draw_text(text_cache, x0 + 20, y0 + 62, connection, (112, 229, 169) if active else (162, 182, 185), 16, False, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x0 + 20, y0 + 103, address, (206, 225, 228), 22, True, True, "lm")


def draw_network_manager(text_cache, snapshot, busy, selected_ssid):
    boxes = network_panel_boxes()
    x0, y0, x1, y1 = boxes["panel"]
    devices = snapshot.get("devices") or {}
    networks = snapshot.get("networks") or []
    draw_logical_rect(0, 0, LOGICAL_W, LOGICAL_H, (2, 8, 12, 196))
    draw_logical_rect(x0, y0, x1, y1, (7, 18, 25, 248))
    draw_logical_line(x0, y0, x1, y0, (93, 205, 192, 205), 2)
    draw_text(text_cache, x0 + 20, y0 + 35, "NETWORK", (230, 245, 247), 26, True, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x0 + 20, y0 + 66, "ETHERNET PREFERRED  ·  WI-FI AUTOMATIC BACKUP", (121, 187, 184), 14, True, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x0 + 20, y0 + 91, "SELECT A WI-FI NETWORK, THEN ENTER ITS KEY", (171, 220, 215), 14, True, False, "lm", family="Liberation Sans")
    draw_picker_button(text_cache, boxes["back"], "BACK", 17)
    draw_network_status_card(text_cache, boxes["ethernet"], "ETHERNET", devices.get("eth0"), True)
    draw_network_status_card(text_cache, boxes["wifi"], "WI-FI", devices.get("wlan0"), False)
    lx0, ly0, lx1, ly1 = boxes["list"]
    draw_text(text_cache, lx0, ly0 + 14, "WI-FI NETWORKS", (207, 232, 234), 18, True, False, "lm", family="Liberation Sans")
    scanning = bool(snapshot.get("scanning"))
    status_label = "SCANNING..." if scanning else ("UPDATING..." if busy else f"{len(networks)} FOUND")
    draw_text(text_cache, lx1, ly0 + 14, status_label, (109, 235, 178) if scanning else (145, 184, 189), 13, True, False, "rm", family="Liberation Sans")
    scan_boxes = network_scan_boxes(networks)
    for network, box in zip(networks, scan_boxes):
        bx0, by0, bx1, by1 = box
        selected = network.get("ssid") == selected_ssid
        active = bool(network.get("active"))
        draw_logical_rect(bx0, by0, bx1, by1, (24, 65, 58, 236) if selected else (14, 31, 40, 230))
        edge = (104, 236, 177, 246) if selected else ((72, 212, 156, 184) if active else (95, 125, 136, 120))
        for ax0, ay0, ax1, ay1 in ((bx0, by0, bx1, by0), (bx0, by1, bx1, by1), (bx0, by0, bx0, by1), (bx1, by0, bx1, by1)):
            draw_logical_line(ax0, ay0, ax1, ay1, edge, 1)
        ssid = fit_station_text(text_cache, str(network.get("ssid", "")), bx1 - bx0 - 26, 17, True, False, family="Liberation Sans")
        draw_text(text_cache, bx0 + 13, by0 + 21, ssid, (232, 246, 247), 17, True, False, "lm", family="Liberation Sans")
        security = "LOCKED" if network.get("security") not in ("", "--") else "OPEN"
        detail = "SELECTED - ENTER WI-FI KEY" if selected else f"{network.get('signal', 0):.0f}%  {security}"
        draw_text(text_cache, bx0 + 13, by1 - 16, detail, (109, 233, 177) if selected or active else (158, 188, 193), 13, True, False, "lm", family="Liberation Sans")
    if not networks and not busy:
        draw_text(text_cache, (lx0 + lx1) / 2, (ly0 + ly1) / 2, "NO NETWORKS YET", (139, 166, 170), 19, True, False, "cm", family="Liberation Sans")
    draw_picker_button(text_cache, boxes["rescan"], "SCANNING" if scanning else "RESCAN", 16, scanning)
    join_label = "ENTER WI-FI KEY" if selected_ssid else "SELECT WI-FI"
    draw_picker_button(text_cache, boxes["join"], join_label, 14 if selected_ssid else 15, bool(selected_ssid) and not busy)
    notice = str(snapshot.get("notice") or "Select a network, then enter its Wi-Fi key.")
    draw_text(text_cache, x0 + 408, y1 - 43, fit_station_text(text_cache, notice, x1 - (x0 + 430) - 18, 15, False, False, family="Liberation Sans"), (241, 175, 121) if not snapshot.get("ok") else (156, 194, 197), 15, False, False, "lm", family="Liberation Sans")


def draw_network_password(text_cache, ssid, value, mode, caps, revealed, busy, error="", placeholder_visible=True):
    boxes = network_password_boxes()
    x0, y0, x1, y1 = boxes["panel"]
    draw_logical_rect(0, 0, LOGICAL_W, LOGICAL_H, (1, 6, 10, 202))
    draw_logical_rect(x0, y0, x1, y1, (8, 20, 27, 250))
    draw_logical_line(x0, y0, x1, y0, (100, 230, 185, 220), 2)
    draw_text(text_cache, x0 + 26, y0 + 30, "JOIN WI-FI", (229, 246, 247), 24, True, False, "lm", family="Liberation Sans")
    draw_text(text_cache, x0 + 26, y0 + 57, fit_station_text(text_cache, ssid, x1 - x0 - 52, 19, False, False, family="Liberation Sans"), (112, 237, 178), 19, False, False, "lm", family="Liberation Sans")
    fx0, fy0, fx1, fy1 = boxes["field"]
    draw_logical_rect(fx0, fy0, fx1, fy1, (4, 12, 17, 246))
    draw_logical_line(fx0, fy0, fx1, fy0, (84, 153, 152, 185), 1)
    field_text = (value if revealed else "*" * len(value)) or ("WI-FI PASSWORD" if placeholder_visible else "")
    field_size = 32 if value else 20
    field_width = boxes["reveal"][0] - fx0 - 28
    rendered_text = fit_station_text(text_cache, field_text, field_width, field_size, False, False, family="Liberation Sans")
    draw_text(text_cache, fx0 + 14, (fy0 + fy1) / 2, rendered_text, (226, 241, 243) if value else (130, 163, 167), field_size, False, False, "lm", family="Liberation Sans")
    draw_network_password_eye(boxes["reveal"], revealed)
    draw_picker_button(text_cache, boxes["mode"], "123" if mode != "symbols" else "ABC", 16)
    draw_picker_button(text_cache, boxes["caps"], "CAPS", 16, caps and mode != "symbols")
    draw_picker_button(text_cache, boxes["clear"], "CLR", 16)
    draw_picker_button(text_cache, boxes["cancel"], "CANCEL", 15)
    draw_picker_button(text_cache, boxes["join"], "JOINING" if busy else "JOIN", 16, bool(value) and not busy)
    for keys, row_x0, row_y0, key_w in network_keyboard_rows(mode, caps):
        for index, key in enumerate(keys):
            box = (row_x0 + index * key_w, row_y0, row_x0 + (index + 1) * key_w - 5, row_y0 + 58)
            draw_picker_button(text_cache, box, "BACK" if key == "<" else key, 14 if key == "<" else 22)
    message = error or "Password stays on this Pi only. Ethernet remains preferred."
    draw_text(text_cache, x0 + 26, y1 - 18, message, (244, 165, 117) if error else (143, 183, 187), 14, False, False, "lm", family="Liberation Sans")


