    audio_transport_graph_open = False
    cpu_utilization_graph_open = False
    asr_panel_open = False
    asr_moon_language_open = False
    deepgram_setup_open = False
    deepgram_setup_engine = "deepgram"
    deepgram_key_value = ""
    deepgram_key_mode = "lower"
    deepgram_key_error = ""
    # Both live overlays have three operator-selectable lanes. Keep their
    # saved lanes distinct so they never obscure each other after a reboot.
    caption_anchor = normalize_caption_anchor(remembered_preferences.get("caption_anchor"), "bottom")
    callsign_anchor = normalize_caption_anchor(remembered_preferences.get("callsign_anchor"), "middle")
    buffer_graph_anchor = normalize_caption_anchor(remembered_preferences.get("buffer_graph_anchor"), "top")
    cpu_graph_anchor = normalize_caption_anchor(remembered_preferences.get("cpu_graph_anchor"), "top")
    if callsign_anchor == caption_anchor:
        callsign_anchor = "middle" if caption_anchor != "middle" else "top"
    caption_box = VOSK_CAPTION_BOX
    caption_translation_toggle_box_live = None
    callsign_box = VOSK_CAPTION_BOX
    buffer_graph_box = None
    cpu_graph_box = None
    audio_volume = audio_output_volume(args)
    saved_volume = remembered_preferences.get("audio_volume")
    if isinstance(saved_volume, (int, float)):
        restored_volume = set_audio_output_volume(args, saved_volume)
        if restored_volume is not None:
            audio_volume = restored_volume
    if audio_volume is None:
        audio_volume = float(saved_volume) if isinstance(saved_volume, (int, float)) else 0.5
    args.output_volume = audio_volume
    audio_volume_last_apply = 0.0

    # The master slider owns the explicit MUTE state at zero. Raising it again
    # resumes listening immediately, so a zero level can never look live while
    # deliberately silencing only the hardware output.
    if audio_volume is not None and audio_volume <= MAIN_VOLUME_MUTE_THRESHOLD:
        state.set_audio_controls(audio_mute=True)

    def apply_main_volume(requested_volume):
        """Apply one master-level gesture and keep mute state in lockstep."""
        nonlocal audio_volume, audio_volume_last_apply
        applied_volume = set_audio_output_volume(args, requested_volume)
        if applied_volume is not None:
            audio_volume = applied_volume
            args.output_volume = applied_volume
            audio_volume_last_apply = time.monotonic()
            state.set_audio_controls(
                audio_mute=applied_volume <= MAIN_VOLUME_MUTE_THRESHOLD
            )
        return applied_volume

    tests_panel_open = False
    openwebrx_test_restore = None
    font_lab_open = False
    font_lab_page = 0
    rtl_lab_open = bool(args.rtl_lab_preview)
    # Dual VFO begins as a visual interaction study. Keeping its state here
    # makes it independent from the one live KiWi client until the second
    # transport/audio path is implemented deliberately.
    dual_vfo_open = bool(args.dual_vfo_preview)
    # Home closes B's transport to release the Kiwi slot, but it does not end
    # the operator's Dual session. Keep B's receiver/tuning profile in RAM so
    # re-entering Dual feels like returning to an instrument, not starting it.
    dual_vfo_has_session = False
    dual_vfo_active = "A"
    dual_vfo_mix = 0.0
    dual_vfo_sources = {
        "A": {"server": args.server, "name": "CURRENT RECEIVER", "location": ""},
        "B": {"server": args.server, "name": "CURRENT RECEIVER", "location": ""},
    }
    dual_vfo_profiles = {
        "A": {"freq_khz": args.freq_khz, "zoom": args.zoom, "mode": radio_mode, "squelch_level": 0},
        "B": {"freq_khz": args.freq_khz, "zoom": args.zoom, "mode": radio_mode, "squelch_level": 0},
    }

    def persisted_dual_source(source, fallback):
        """Return the small, durable portion of a Dual receiver entry."""
        source = source if isinstance(source, dict) else {}
        server = str(source.get("server") or fallback["server"])
        parsed = urlparse(server)
        if parsed.scheme not in ("http", "https") or not parsed.hostname:
            server = fallback["server"]
        return {
            "server": server,
            "name": str(source.get("name") or fallback["name"]),
            "location": str(source.get("location") or fallback["location"]),
        }

    def persisted_dual_profile(profile, fallback):
        """Validate a saved Dual profile before it can start a Kiwi client."""
        profile = profile if isinstance(profile, dict) else {}
        restored = dict(fallback)
        try:
            frequency = float(profile.get("freq_khz", restored["freq_khz"]))
            if 0.0 <= frequency <= TUNING_MAX_KHZ:
                restored["freq_khz"] = frequency
        except (TypeError, ValueError):
            pass
        try:
            restored["zoom"] = int(clamp(int(profile.get("zoom", restored["zoom"])), 0, args.max_zoom))
        except (TypeError, ValueError):
            pass
        mode = str(profile.get("mode", restored["mode"])).upper()
        if mode in KIWI_RADIO_MODES:
            restored["mode"] = mode
        for edge in ("low_cut", "high_cut"):
            try:
                restored[edge] = int(profile[edge])
            except (KeyError, TypeError, ValueError):
                pass
        try:
            restored["squelch_level"] = int(clamp(int(profile.get("squelch_level", 0)), 0, 99))
        except (TypeError, ValueError):
            pass
        controls = profile.get("audio_controls")
        if isinstance(controls, dict):
            # Keep only the names accepted by SharedState.set_audio_controls.
            allowed = {
                "squelch_level", "squelch_tail", "audio_mute", "agc_enabled", "agc_hang",
                "agc_threshold", "agc_slope", "agc_decay", "agc_manual_gain", "deemphasis",
                "nb_algo", "nr_algo", "denoise_level", "voice_clean_enabled", "voice_clean_level",
                "hf_enhance_level", "tone_profile", "autonotch_enabled",
            }
            restored["audio_controls"] = {
                name: value for name, value in controls.items()
                if name in allowed and isinstance(value, (bool, int, float, str))
            }
        return restored

    # B must survive more than a Home round-trip: service restarts used to
    # rebuild it from A/current receiver, silently turning it into Local Kiwi.
    saved_dual_vfo = remembered_preferences.get("dual_vfo", {})
    if isinstance(saved_dual_vfo, dict):
        default_sources = {name: dict(source) for name, source in dual_vfo_sources.items()}
        default_profiles = {name: dict(profile) for name, profile in dual_vfo_profiles.items()}
        saved_sources = saved_dual_vfo.get("sources", {})
        saved_profiles = saved_dual_vfo.get("profiles", {})
        saved_b_server = (
            str(saved_sources.get("B", {}).get("server", "")).strip()
            if isinstance(saved_sources, dict) and isinstance(saved_sources.get("B"), dict)
            else ""
        )
        # A valid B endpoint is sufficient proof of a former Dual session.
        # Older preference files may lack `has_session`; do not erase their B
        # receiver just because that cosmetic flag was absent or stale.
        has_saved_dual_session = bool(saved_dual_vfo.get("has_session") or saved_b_server)
        if has_saved_dual_session and isinstance(saved_sources, dict) and isinstance(saved_profiles, dict):
            dual_vfo_sources = {
                name: persisted_dual_source(saved_sources.get(name), default_sources[name])
                for name in ("A", "B")
            }
            dual_vfo_profiles = {
                name: persisted_dual_profile(saved_profiles.get(name), default_profiles[name])
                for name in ("A", "B")
            }
            dual_vfo_active = saved_dual_vfo.get("active") if saved_dual_vfo.get("active") in ("A", "B") else "A"
            try:
                dual_vfo_mix = clamp(float(saved_dual_vfo.get("mix", 0.0)), 0.0, 1.0)
            except (TypeError, ValueError):
                dual_vfo_mix = 0.0
            dual_vfo_has_session = True
    dual_vfo_picker_open = False
    dual_vfo_picker_target = "A"
    dual_vfo_picker_page = 0
    dual_vfo_mode_open = False
    dual_vfo_mode_target = "A"
    dual_vfo_gesture_vfo = None
    dual_vfo_dragging = False
    dual_vfo_start_freq = args.freq_khz
    dual_vfo_start_zoom = args.zoom
    dual_vfo_pinch_distance = None

    def sync_dual_vfo_b_state():
        """Publish the editable B profile to its own live Kiwi state."""
        source = dict(dual_vfo_sources.get("B", {}))
        profile = dict(dual_vfo_profiles.get("B", {}))
        target_server = str(source.get("server") or args.server)
        current_server, _freq, _zoom, _dbm, _view_gen, _server_gen = dual_b_state.snapshot()
        if target_server != current_server:
            dual_b_state.set_server(target_server)
            drain_queue(dual_b_line_queue)
            dual_b_wf_texture.clear()
        dual_b_state.set_view(
            freq_khz=float(profile.get("freq_khz", args.freq_khz)),
            zoom=int(profile.get("zoom", args.zoom)),
        )
        desired_mode = str(profile.get("mode", radio_mode)).lower()
        current_mode, _low_cut, _high_cut, _radio_gen = dual_b_state.radio_snapshot()
        if desired_mode != current_mode:
            actual_mode, low_cut, high_cut, _generation = dual_b_state.set_radio_mode(desired_mode)
            profile.update({"mode": actual_mode.upper(), "low_cut": low_cut, "high_cut": high_cut})
            dual_vfo_profiles["B"] = profile
        controls = dict(profile.get("audio_controls", {}))
        controls["squelch_level"] = int(profile.get("squelch_level", controls.get("squelch_level", 0)) or 0)
        if controls:
            dual_b_state.set_audio_controls(**controls)

    def start_dual_vfo_clients():
        """Start B's real SND/W/F clients and make A+B own one PCM sink."""
        nonlocal dual_b_stop_event, dual_b_snd_thread, dual_b_wf_thread
        # B is deliberately dormant outside the workspace. Resume its state
        # only as part of an explicit Dual entry, after a prior hard teardown.
        dual_b_state.set_stream_paused(False)
        sync_dual_vfo_b_state()
        dual_audio_mixer.start(dual_vfo_mix)
        dual_program_matcher.start()
        if dual_b_stop_event is not None and not dual_b_stop_event.is_set():
            return
        dual_b_stop_event = threading.Event()
        dual_b_snd_thread = threading.Thread(
            target=snd_meter_worker,
            args=(args, dual_b_stop_event, dual_b_state),
            kwargs={
                "dual_mixer": dual_audio_mixer,
                "dual_source": "B",
                "dual_matcher": dual_program_matcher,
                "enable_listener_dsp": False,
                "waterfall_line_queue": dual_b_line_queue,
                # A second listener must present a distinct Kiwi identity.
                # Some receivers tear down a duplicate name even with a
                # correctly unique SND/W/F session timestamp.
                "listener_name": f"{args.user}-VFOB",
            },
            name="dual-vfo-b-snd",
            daemon=True,
        )
        dual_b_wf_thread = threading.Thread(
            target=waterfall_worker,
            args=(args, dual_b_line_queue, dual_b_stop_event, dual_b_state),
            kwargs={"listener_name": f"{args.user}-VFOB"},
            name="dual-vfo-b-waterfall",
            daemon=True,
        )
        dual_b_snd_thread.start()
        dual_b_wf_thread.start()
        print("gl dual VFO B client started", flush=True)

    def stop_dual_vfo_clients():
        """Hard-release B's Kiwi slots immediately when Dual is dismissed."""
        nonlocal dual_b_stop_event, dual_b_snd_thread, dual_b_wf_thread
        was_running = dual_b_stop_event is not None or dual_audio_mixer.active_snapshot()
        dual_program_matcher.stop()
        dual_audio_mixer.stop()
        # Do not merely ask the threads to stop: close the live B transports
        # now, so the Kiwi server frees both listener slots before Home draws.
        dual_b_state.set_stream_paused(True)
        if dual_b_stop_event is not None:
            dual_b_stop_event.set()
        if dual_b_snd_thread is not None:
            dual_b_snd_thread.join(timeout=1.2)
        if dual_b_wf_thread is not None:
            dual_b_wf_thread.join(timeout=1.2)
        dual_b_stop_event = None
        dual_b_snd_thread = None
        dual_b_wf_thread = None
        drain_queue(dual_b_line_queue)
        if was_running:
            print("gl dual VFO B client stopped", flush=True)

    def dual_vfo_b_status():
        """Return B's confirmed programme result through a brief reconnect."""
        _server, _freq, _zoom, _dbm, _view_generation, server_generation = dual_b_state.snapshot()
        match_status = dual_program_matcher.status_snapshot()
        # A conclusion applies to the unchanged A/B source signature, not to
        # the incidental state of the latest WebSocket. Keep it visible while
        # Kiwi reconnects one half of the pair; configure() clears it as soon
        # as the operator changes receiver, frequency, or mode.
        if match_status.startswith("MATCH "):
            return match_status
        if dual_b_state.audio_stream_ready_snapshot(server_generation):
            return match_status if match_status not in ("OFF", "WAITING") else "LIVE"
        return str(dual_b_state.connection_snapshot() or "CONNECTING").replace("_", " ").upper()

    wspr_preferences = remembered_preferences.get("wspr", {})
    if not isinstance(wspr_preferences, dict):
        wspr_preferences = {}
    wspr_known_bands = {label for label, _frequency in WSPR_BANDS}
    wspr_sessions = {
        str(label) for label in wspr_preferences.get("sessions", ())
        if str(label) in wspr_known_bands
    }
    # A tile is a real receiver/band monitor configuration. Keep the old
    # selected-band set only for history compatibility; it never silently
    # opens public receiver sockets until the operator creates a tile.
    wspr_tiles = []
    for raw_tile in wspr_preferences.get("tiles", ()):
        if not isinstance(raw_tile, dict):
            continue
        band = str(raw_tile.get("band", ""))
        frequency = wspr_band_frequency(band)
        server_value = str(raw_tile.get("server", "")).strip()
        if frequency is None or not server_value:
            continue
        wspr_tiles.append({
            "id": str(raw_tile.get("id") or f"saved-{len(wspr_tiles)}"),
            "band": band,
            "freq_khz": float(raw_tile.get("freq_khz", frequency) or frequency),
            "server": server_value,
            "name": str(raw_tile.get("name", "CURRENT RECEIVER") or "CURRENT RECEIVER"),
            "location": str(raw_tile.get("location", "") or ""),
            "paused": bool(raw_tile.get("paused", False)),
            "view": int(raw_tile.get("view", 0) or 0) % 3,
        })
    try:
        wspr_workspace_page = int(wspr_preferences.get("workspace_page", 0))
    except (TypeError, ValueError):
        wspr_workspace_page = 0
    wspr_workspace_page = int(clamp(wspr_workspace_page, 0, wspr_workspace_page_count(wspr_tiles) - 1))
    try:
        wspr_workspace_scroll = float(wspr_preferences.get("workspace_scroll", 0.0))
    except (TypeError, ValueError):
        # Preserve a useful approximate location for the old paged view on
        # its first launch after migration.
        wspr_workspace_scroll = float(wspr_workspace_page * (LOGICAL_H - WSPR_WORKSPACE_HEADER_H - 16))
    wspr_workspace_scroll = clamp(wspr_workspace_scroll, 0.0, wspr_workspace_scroll_max(wspr_tiles))
    wspr_workspace_scroll_start = wspr_workspace_scroll
    wspr_workspace_dragged = False
    wspr_add_open = False
    wspr_add_band = "20"
