    wspr_distance_cache = WSPRDistanceHistoryCache(args.wspr_log_file)
    wspr_distance_cache.start()
    wspr_mini_distance_cache = WSPRMiniDistanceGraphCache()
    # The decoder ranking is similarly hydrated off-thread. Its compact
    # sidecar retains personal best hourly decode rates across reboots.
    wspr_decode_rates = WSPRDecodeRateTracker(args.wspr_log_file)
    wspr_decode_rates.start()
    wspr_mini_textures = {}
    wspr_selected_band = str(wspr_preferences.get("selected_band", "20"))
    if wspr_selected_band not in wspr_known_bands:
        wspr_selected_band = "20"
    try:
        wspr_graph_window_index = int(wspr_preferences.get("graph_window", 0))
    except (TypeError, ValueError):
        wspr_graph_window_index = 0
    try:
        wspr_band_page = int(wspr_preferences.get("band_page", 0))
    except (TypeError, ValueError):
        wspr_band_page = 0
    wspr_graph_window_index = int(clamp(wspr_graph_window_index, 0, len(WSPR_GRAPH_WINDOWS) - 1))
    wspr_band_page = int(clamp(wspr_band_page, 0, wspr_band_page_count() - 1))
    wspr_history = deque(maxlen=max(256, int(WSPR_HISTORY_SECONDS / 1.5)))
    wspr_next_sample = 0.0
    wspr_next_log_at = 0.0
    wspr_panel_open = args.wspr_preview
    wspr_identity_preferences = remembered_preferences.get("wspr_identity", {})
    if not isinstance(wspr_identity_preferences, dict):
        wspr_identity_preferences = {}
    wspr_identity_values = {
        "reporter": str(wspr_identity_preferences.get("reporter", "SWL") or "SWL").strip().upper() or "SWL",
        "grid": str(wspr_identity_preferences.get("grid", "") or "").strip().upper(),
    }
    saved_grid_source = str(wspr_identity_preferences.get("grid_source", "")).strip().lower()
    wspr_identity_grid_source = (
        saved_grid_source
        if saved_grid_source in ("local", "manual")
        else ("manual" if wspr_grid_is_valid(wspr_identity_values["grid"]) else "local")
    )
    wspr_local_grid = ""
    wspr_local_grid_queue = queue.Queue(maxsize=1)

    def refresh_local_wspr_grid():
        grid = kiwi_status_grid(LOCAL_KIWI_SERVER)
        if grid:
            try:
                wspr_local_grid_queue.put_nowait(grid)
            except queue.Full:
                pass

    # Local Kiwi location is authoritative for a local WSPR receiver. Do the
    # small status read off the render thread, then use it as the automatic
    # distance reference unless the operator has explicitly supplied another.
    threading.Thread(target=refresh_local_wspr_grid, name="wspr-local-grid", daemon=True).start()
    wspr_identity_open = False
    wspr_identity_field = "reporter"
    wspr_identity_error = ""
    globe_open = False
    globe_receivers = load_globe_receivers()
    if globe_receivers:
        # The map feed is the current worldwide directory. Use its cached
        # entries immediately instead of limiting the station browser to the
        # small built-in fallback while a live refresh is in progress.
        all_stations = stations_from_globe_receivers(globe_receivers)
        stations = filtered_stations(all_stations, station_query, station_sort, station_route_filter, favorite_servers)
    globe_result_queue = queue.Queue(maxsize=1)
    globe_fetch_started = True
    threading.Thread(
        target=refresh_globe_receivers,
        args=(globe_result_queue,), daemon=True,
    ).start()
    globe_yaw = math.radians(-20)
    globe_pitch = math.radians(18)
    globe_scale = 0.72
    globe_listeners = []
    globe_replacement_slots = []
    globe_scouts = []
    globe_scout_history = []
    globe_scout_measurements = {}
    globe_next_scout_rotation = 0.0
    globe_next_scout_promotion = 0.0
    globe_next_scout_review = 0.0
    globe_scout_search_radius_km = SCOUT_SEARCH_START_KM
    globe_scout_scanned_servers = set()
    globe_scout_local_rounds = 0
    globe_heat_frequency_khz = None
    globe_heat_radio_mode = None
    globe_anchor = None
    globe_active_server = None
    globe_status = "Tap a region to warm 3 listeners and launch 4 scouts"
    globe_start_yaw = globe_yaw
    globe_start_pitch = globe_pitch
    globe_pinch_distance = None
    globe_pinch_active = False
    globe_failed_servers = set()
    retune_pattern_index = 0
    retune_sweep = None
    dj_tune_open = False
    dj_origin_khz = args.freq_khz
    dj_current_khz = args.freq_khz
    dj_step_hz = 100
    dj_range_khz = 5.0
    dj_drag_remainder_hz = 0.0
    filter_panel_open = False
    filter_drag_edge = None
    filter_drag_center = 0.0
    filter_drag_audio_center = 0.0
    filter_drag_limit = FILTER_LIMIT_HZ
    filter_custom_width = bool(remembered_preferences.get("filter_custom_width", False))
    frequency_entry_open = args.frequency_keypad_preview
    frequency_entry_value = f"{args.freq_khz / 1000.0:.6f}" if frequency_entry_open else ""
    frequency_entry_invalid = False
    frequency_entry_replace_on_digit = False
    station_scroll = 0
    saved_digital_mode = remembered_preferences.get("digital_mode")
    digital_mode = saved_digital_mode if saved_digital_mode in ("DIG", "IQ") else "DIG"
    saved_tune_step_hz = remembered_preferences.get("tune_step_hz")
    tune_step_hz = max(1, int(saved_tune_step_hz)) if isinstance(saved_tune_step_hz, (int, float)) else args.tune_step_hz
    rc28_zoom_detents = 0
    rc28_zoom_last_at = 0.0
    rc28_dial_mode = "TUNE"
    # The review pool is intentionally reset each launch, but the operator's
    # marked candidates are durable preferences so good options accumulate.
    compact_font_review_families = list(COMPACT_FONT_REVIEW_FAMILIES)
    # The temporary font lab can still preview alternatives, but the live
    # instrument always comes up in the unified Oxanium treatment.
    compact_frequency_font_family = COMPACT_FREQUENCY_FONT_FAMILY
    compact_frequency_font_index = compact_font_review_families.index(compact_frequency_font_family)
    compact_font_review_open = False
    saved_compact_font_likes = remembered_preferences.get("compact_font_likes", ())
    if not isinstance(saved_compact_font_likes, (list, tuple)):
        saved_compact_font_likes = ()
    compact_font_review_liked = {
        str(family) for family in saved_compact_font_likes
        if str(family) in COMPACT_FONT_REVIEW_FAMILIES
    }
    active = False
    raw_x = raw_y = None
    current_slot = 0
    mt_slots = {}
    touch_started = False
    gesture = None
    swipe_started = False
    start_x = start_freq = None
    start_y = 0
    start_scroll = 0
    picker_dragged = False
    start_menu_scroll = 0.0
    start_time = 0.0
    last_move_x = 0.0
    last_move_t = 0.0
    swipe_velocity_px_s = 0.0
    last_swipe_direction = 0
    last_swipe_time = 0.0
    repeat_swipe_count = 0
    active_swipe_boost = 1.0
    repeat_zoom_applied = False
    repeat_zoom_changed = False
    fast_sweep_zoom_applied = False
    auto_zoom_levels_used = 0
    inertia_velocity_khz_s = 0.0
    inertia_last_t = time.monotonic()
    start_span = display_span
    candidate_freq = display_freq
    last_x = None

    # Receiver, tuning, waterfall, and listener preferences live in one tiny
    # JSON file. A single timer batches any changed state into one atomic write
    # every 30 seconds, preventing live tuning from becoming flash churn.
    persisted_frequency_khz = args.freq_khz
    observed_frequency_khz = args.freq_khz
    next_preferences_poll = 0.0
    preferences_due_at = 0.0
    preferences_dirty = bool(args.remember_receiver and "preferences" not in remembered_preferences)
    observed_preferences_signature = None
    saved_preferences_signature = None

    def current_preferences():
        _server, _freq_khz, zoom, _smeter, _generation, _server_generation = state.snapshot()
        _mode, low_cut, high_cut, _radio_generation = state.radio_snapshot()
        floor, ceiling, speed, auto, palette, _wf_generation = state.waterfall_snapshot()
        spectrum_enabled, _spectrum_values, _spectrum_peak_values = state.spectrum_snapshot()
        audio_controls, _audio_generation = state.audio_controls_snapshot()
        return {
            "audio": {
                "squelch_level": audio_controls["squelch_level"],
                "squelch_tail": audio_controls["squelch_tail"],
                "audio_mute": audio_controls["mute"],
                "agc_enabled": audio_controls["agc"],
                "agc_hang": audio_controls["agc_hang"],
                "agc_threshold": audio_controls["agc_threshold"],
                "agc_slope": audio_controls["agc_slope"],
                "agc_decay": audio_controls["agc_decay"],
                "agc_manual_gain": audio_controls["agc_manual_gain"],
                "deemphasis": audio_controls["deemphasis"],
                "nb_algo": audio_controls["nb_algo"],
                "nr_algo": audio_controls["nr_algo"],
                "denoise_level": audio_controls["denoise_level"],
                "voice_clean_enabled": audio_controls["voice_clean"],
                "voice_clean_level": audio_controls["voice_clean_level"],
                "hf_enhance_level": audio_controls["hf_enhance_level"],
                "tone_profile": audio_controls["tone_profile"],
                "voice_clean_profile": 3,
                "autonotch_enabled": audio_controls["autonotch"],
            },
            "audio_volume": None if audio_volume is None else round(float(audio_volume), 3),
            "audio_backend": selected_audio_backend(args),
            "digital_mode": digital_mode,
            "filter": {"low_cut": low_cut, "high_cut": high_cut},
            "filter_custom_width": bool(filter_custom_width),
            "wspr": {
                "sessions": sorted(wspr_sessions),
                "selected_band": wspr_selected_band,
                "decoder_profile": wspr_decoder_profile,
                "decoder_osd_depth": int(wspr_decoder_osd_depth),
                "graph_window": int(wspr_graph_window_index),
                "distance_graph_window": int(wspr_expanded_graph_window),
                "band_page": int(wspr_band_page),
                "workspace_page": int(wspr_workspace_page),
                "workspace_scroll": round(float(wspr_workspace_scroll), 1),
                "tiles": [
                    {
                        "id": str(tile.get("id")),
                        "band": str(tile.get("band")),
                        "freq_khz": round(float(tile.get("freq_khz", 0.0)), 4),
                        "server": str(tile.get("server", "")),
                        "name": str(tile.get("name", "CURRENT RECEIVER")),
                        "location": str(tile.get("location", "")),
                        "paused": bool(tile.get("paused", False)),
                        "view": int(tile.get("view", 0) or 0) % 3,
                    }
                    for tile in wspr_tiles
                ],
            },
            "wspr_identity": {
                "reporter": wspr_log_identity(wspr_identity_values)["rx_id"],
                "grid": str(wspr_identity_values.get("grid", "")).strip().upper(),
                "grid_source": wspr_identity_grid_source,
            },
            "spectrum_enabled": bool(spectrum_enabled),
            "instrument_layout": instrument_layout,
            "compact_font_likes": sorted(compact_font_review_liked),
            "compact_frequency_font_family": compact_frequency_font_family,
            "asr_engine": state.transcription_snapshot()[1],
            "caption_mode": state.caption_mode_snapshot(),
            "callsign_enabled": state.callsign_snapshot()[0],
            "caption_anchor": caption_anchor,
            "callsign_anchor": callsign_anchor,
            "buffer_graph_anchor": buffer_graph_anchor,
            "cpu_graph_anchor": cpu_graph_anchor,
            "tune_step_hz": int(tune_step_hz),
            "waterfall": {
                "floor": round(float(floor), 1),
                "ceil": round(float(ceiling), 1),
                "speed": int(speed),
                "auto": bool(auto),
                "palette": palette,
            },
            "dual_vfo": {
                "has_session": bool(dual_vfo_has_session),
                "active": dual_vfo_active if dual_vfo_active in ("A", "B") else "A",
                "mix": round(float(dual_vfo_mix), 3),
                "sources": {
                    name: persisted_dual_source(
                        dual_vfo_sources.get(name),
                        {"server": args.server, "name": "CURRENT RECEIVER", "location": ""},
                    )
                    for name in ("A", "B")
                },
                "profiles": {
                    name: persisted_dual_profile(
                        dual_vfo_profiles.get(name),
                        {"freq_khz": args.freq_khz, "zoom": args.zoom, "mode": radio_mode, "squelch_level": 0},
                    )
                    for name in ("A", "B")
                },
            },
            "zoom": int(zoom),
        }

    def preferences_signature(preferences):
        server, _freq_khz, _zoom, _smeter, _generation, _server_generation = state.snapshot()
        payload = {
            "server": server,
            "radio_mode": radio_mode if manual_radio_mode else None,
            "preferences": preferences,
        }
        return json.dumps(payload, sort_keys=True, separators=(",", ":"))

    def write_remembered_view(save_current_frequency=False, force=False):
        nonlocal persisted_frequency_khz, preferences_dirty, preferences_due_at, saved_preferences_signature
        if not args.remember_receiver:
            return False
        server, freq_khz, zoom, _smeter, _generation, _server_generation = state.snapshot()
        preferences = current_preferences()
        signature = preferences_signature(preferences)
        frequency_changed = abs(persisted_frequency_khz - freq_khz) > 0.0005
        if not force and not preferences_dirty and signature == saved_preferences_signature and not (save_current_frequency and frequency_changed):
            return False
        if save_current_frequency:
            persisted_frequency_khz = freq_khz
        save_remembered_view(
            args.receiver_state_file,
            server,
            persisted_frequency_khz,
            zoom,
            radio_mode,
            manual_radio_mode,
            preferences,
        )
        saved_preferences_signature = signature
        preferences_dirty = False
        preferences_due_at = 0.0
        return True

    def observe_preferences(now):
        nonlocal observed_frequency_khz, next_preferences_poll
        nonlocal observed_preferences_signature, preferences_dirty, preferences_due_at
        if not args.remember_receiver or now < next_preferences_poll:
            return
        next_preferences_poll = now + PREFERENCES_POLL_SECONDS
        _server, freq_khz, _zoom, _smeter, _generation, _server_generation = state.snapshot()
        if abs(freq_khz - observed_frequency_khz) > 0.0005:
            observed_frequency_khz = freq_khz
        preferences = current_preferences()
        signature = preferences_signature(preferences)
        if signature != observed_preferences_signature:
            observed_preferences_signature = signature
            if signature != saved_preferences_signature:
                preferences_dirty = True
        changed = preferences_dirty or abs(freq_khz - persisted_frequency_khz) > 0.0005
        if changed and preferences_due_at <= 0.0:
            preferences_due_at = now + PERSISTENCE_INTERVAL_SECONDS
        if changed and now >= preferences_due_at:
            # One write captures the latest tuned frequency and waterfall
            # controls together, even when both changed during the interval.
            write_remembered_view(save_current_frequency=True)

    initial_preferences = current_preferences()
    observed_preferences_signature = preferences_signature(initial_preferences)
    saved_preferences_signature = observed_preferences_signature

    def write_wspr_local_log(event, smeter_dbm=None, smeter_peak_dbm=None, **extra):
        """Capture local WSPR operating context for later search and decode joins."""
        server, freq_khz, zoom, live_smeter, _generation, _server_generation = state.snapshot()
        mode, low_cut, high_cut, _radio_generation = state.radio_snapshot()
        identity = wspr_log_identity(wspr_identity_values)
        record = {
            "reporter": identity["rx_id"],
            "grid": identity["rx_grid"],
            "receiver": server,
            "frequency_khz": round(float(freq_khz), 3),
            "zoom": int(zoom),
            "mode": str(mode).upper(),
            "filter_hz": {"low": int(low_cut), "high": int(high_cut)},
            "selected_band_m": wspr_selected_band,
            "armed_bands_m": sorted(wspr_sessions),
            "smeter_dbm": round(float(live_smeter if smeter_dbm is None else smeter_dbm), 1),
        }
        if smeter_peak_dbm is not None:
            record["smeter_peak_dbm"] = round(float(smeter_peak_dbm), 1)
        record.update(extra)
        try:
            append_wspr_local_log(args.wspr_log_file, event, record)
            # New WSPR decodes are folded into all four graph spans once here,
            # never re-parsed from disk by the OpenGL render loop.
            wspr_distance_cache.ingest(event, record)
            wspr_decode_rates.ingest(event, record)
        except OSError as exc:
            print(f"gl WSPR local log {exc}", flush=True)

    def remember_current_view():
        observe_preferences(time.monotonic())

    # Decoder workers run outside the render loop. Give them the same durable,
    # searchable JSONL sink as the rest of the WSPR workspace once the closure
    # has access to the live operator context above.
    wspr_monitor.set_log_callback(write_wspr_local_log)
    write_wspr_local_log("renderer_started")

    def persist_before_service_shutdown(signum, _frame):
        """Commit the batched settings before systemd stops the renderer.

        The normal 30-second write protects the SD card from slider churn, but
        systemd otherwise terminates Python before its ``finally`` block can
        save a just-adjusted drawer. Treat a controlled reboot/restart as the
        one exception and force one atomic write of the complete preference
        document.
        """
        wspr_distance_cache.flush()
        wspr_decode_rates.flush()
        write_remembered_view(save_current_frequency=True, force=True)
        print(f"gl persisted receiver preferences before signal {signum}", flush=True)
        raise SystemExit(0)

    signal.signal(signal.SIGTERM, persist_before_service_shutdown)

    def occupied_overlay_lanes(exclude=None):
        """Return the lanes currently used by visible movable overlays.

        The ASR caption, callsign caption and the two diagnostic graphs share
        a deliberately small three-lane layout.  Only one diagnostic graph is
        open at a time, so every visible overlay can have a lane of its own.
        Keeping the ownership here rather than in each touch handler prevents
        a persisted position or a tap from placing two windows on one another.
        """
        occupied = set()
        transcription_enabled, _engine, _lines, _partial, _status, _generation = state.transcription_snapshot()
        callsign_enabled, _value, _message, _status, _updated_at = state.callsign_snapshot()
        if transcription_enabled and exclude != "asr":
            occupied.add(caption_anchor)
        if callsign_enabled and exclude != "ham":
            occupied.add(callsign_anchor)
        if audio_transport_graph_open and exclude != "buffer":
            occupied.add(buffer_graph_anchor)
        if cpu_utilization_graph_open and exclude != "cpu":
            occupied.add(cpu_graph_anchor)
        return occupied

    def available_overlay_lane(which, target_anchor):
        """Choose the requested lane or the next free one, wrapping around."""
        target_anchor = normalize_caption_anchor(target_anchor)
        occupied = occupied_overlay_lanes(exclude=which)
        candidates = [
            ASR_CAPTION_ANCHORS[(ASR_CAPTION_ANCHORS.index(target_anchor) + offset) % len(ASR_CAPTION_ANCHORS)]
            for offset in range(len(ASR_CAPTION_ANCHORS))
        ]
        for lane in candidates:
            if lane not in occupied:
                return lane
        # This is defensive only: at most three overlays can be visible.
        # Retaining the requested lane is less surprising than silently
        # jumping to a fixed position should another overlay type be added.
        return target_anchor

    def move_overlay_to_lane(which, target_anchor):
        """Move ASR/HAM text to an unoccupied shared overlay lane."""
        nonlocal caption_anchor, callsign_anchor, preferences_dirty
        target_anchor = available_overlay_lane(which, target_anchor)
        if which == "asr":
            caption_anchor = target_anchor
        else:
            callsign_anchor = target_anchor
        preferences_dirty = True
        write_remembered_view(force=True)

    def next_overlay_lane(anchor):
        anchor = normalize_caption_anchor(anchor)
        return ASR_CAPTION_ANCHORS[(ASR_CAPTION_ANCHORS.index(anchor) + 1) % len(ASR_CAPTION_ANCHORS)]

    def move_monitoring_graph_to_lane(which, target_anchor):
        """Move a diagnostic graph to a free ASR/diagnostics lane."""
        nonlocal buffer_graph_anchor, cpu_graph_anchor, preferences_dirty
        target_anchor = available_overlay_lane(which, target_anchor)
        if which == "buffer":
            buffer_graph_anchor = target_anchor
        else:
            cpu_graph_anchor = target_anchor
        preferences_dirty = True
        write_remembered_view(force=True)

    def apply_band_default(freq_khz):
        """Follow the conventional 10 MHz split until the operator takes over."""
        nonlocal radio_mode, auto_sideband_mode
        # The retune test is observational. It must not unexpectedly change
        # the current demodulator while it crosses a nearby band threshold.
        if retune_sweep is not None:
            return
        desired_mode = default_sideband_mode(freq_khz)
        if manual_radio_mode or desired_mode == auto_sideband_mode:
            return
        radio_mode = desired_mode
        auto_sideband_mode = desired_mode
        state.set_radio_mode(radio_mode)
        print(f"gl auto sideband {radio_mode.lower()} freq={freq_khz:.3f}", flush=True)

    def controls_alpha(now=None):
        now = now or time.monotonic()
        if menu_open or picker_open or radio_setup_open or band_navigation_open or display_setup_open or audio_panel_open or asr_panel_open or deepgram_setup_open or tests_panel_open or font_lab_open or rtl_lab_open or wspr_panel_open or wspr_identity_open or globe_open or dj_tune_open or filter_panel_open or frequency_entry_open or now <= controls_active_until:
            return 1.0
        fade_t = (now - controls_active_until) / CONTROL_FADE_SECONDS
        return clamp(1.0 - fade_t, 0.0, 1.0)

    def controls_quiet(now=None):
        return controls_alpha(now) <= 0.05

    def waterfall_focus_progress(now=None):
        """Keep the waterfall stable; touch only reveals controls."""
        return 0.0

    def wake_controls():
        nonlocal controls_active_until, drawer_last_interaction_at
        now = time.monotonic()
        controls_active_until = now + CONTROL_QUIET_SECONDS
        # A touch on the waterfall behind a right-rail drawer is still a real
        # interaction. Keep the drawer available while it is being used, but
        # return to Home after five genuinely quiet minutes.
        drawer_last_interaction_at = now

    def animate_to(freq_khz, span_khz, duration=0.20):
        nonlocal anim_from_freq, anim_from_span, anim_to_freq, anim_to_span, anim_start, anim_duration
        nonlocal display_freq, display_span
        anim_from_freq = display_freq
        anim_from_span = display_span
        anim_to_freq = freq_khz
        anim_to_span = span_khz
        anim_start = time.monotonic()
        anim_duration = max(0.001, duration)

    def update_animation():
        nonlocal display_freq, display_span, anim_start
        if anim_start <= 0:
            return
        t = (time.monotonic() - anim_start) / anim_duration
        if t >= 1.0:
            display_freq = anim_to_freq
            display_span = anim_to_span
            anim_start = 0.0
            return
        e = ease_out_cubic(t)
        display_freq = anim_from_freq + (anim_to_freq - anim_from_freq) * e
        display_span = anim_from_span + (anim_to_span - anim_from_span) * e

    def active_tuning_bounds():
        if state.external_waterfall_snapshot() or rtl_lab.is_running():
            return rtl_lab.tuning_bounds()
        return 0.0, TUNING_MAX_KHZ

    def clamp_active_frequency(value):
        low, high = active_tuning_bounds()
        return clamp(float(value), low, high)

    def active_waterfall_center(tuned_khz, span_khz):
        if state.external_waterfall_snapshot() or rtl_lab.is_running():
            return float(tuned_khz)
        return waterfall_view_center_khz(tuned_khz, span_khz)

    def active_source_span_khz(zoom_level):
        if state.external_waterfall_snapshot() or rtl_lab.is_running():
            return rtl_lab.source_span_khz()
        return kiwi.zoom_source_span_khz(zoom_level)

    def change_zoom(delta, animation_duration=0.22):
        nonlocal zoom_osd_until, auto_zoom_levels_used
        wake_controls()
        _server, freq_khz, zoom, _smeter, _gen, _server_gen = state.snapshot()
        minimum_zoom = rtl_lab.minimum_zoom() if (state.external_waterfall_snapshot() or rtl_lab.is_running()) else 0
        new_zoom = clamp(zoom + delta, minimum_zoom, args.max_zoom)
        if new_zoom == zoom:
            zoom_osd_until = time.monotonic() + args.zoom_osd_seconds
            return False
        freq_khz, new_zoom, _gen = state.set_view(zoom=new_zoom)
        remember_current_view()
        auto_zoom_levels_used = 0
        animate_to(freq_khz, kiwi.zoom_to_span_khz(new_zoom), animation_duration)
        zoom_osd_until = time.monotonic() + args.zoom_osd_seconds
        print(f"gl zoom {new_zoom} span {kiwi.zoom_to_span_khz(new_zoom):.1f} kHz", flush=True)
        return True

    def apply_rc28_events():
        """Apply RC-28 Tune/Zoom/Width/Volume editing on the render thread."""
        nonlocal display_freq, candidate_freq, anim_start, inertia_velocity_khz_s
        nonlocal rc28_zoom_detents, rc28_zoom_last_at, rc28_dial_mode, rc28_mode_osd_until
        for kind, value in rc28_input.drain():
            if kind == "button":
                if value == "cycle_dial_mode":
                    # The push control is the simple operational pair: Tune
                    # and Zoom. Function buttons own their temporary filter
                    # edit modes, so a press from either returns here cleanly.
                    rc28_dial_mode = "TUNE" if rc28_dial_mode == "ZOOM" else "ZOOM"
                elif value == "toggle_passband_width":
                    rc28_dial_mode = "TUNE" if rc28_dial_mode == "WIDTH" else "WIDTH"
                elif value == "toggle_volume":
                    rc28_dial_mode = "TUNE" if rc28_dial_mode == "VOLUME" else "VOLUME"
                else:
                    continue
                rc28_zoom_detents = 0
                rc28_mode_osd_until = time.monotonic() + 1.7
                wake_controls()
                print(f"gl RC-28 dial mode {rc28_dial_mode}", flush=True)
                continue

            if kind == "dial" and rc28_dial_mode == "TUNE":
                _server, freq_khz, zoom, _smeter, _generation, _server_generation = state.snapshot()
                step_hz = finger_tune_step_hz(zoom, tune_step_hz)
                frequency = clamp_active_frequency(freq_khz + int(value) * step_hz / 1000.0)
                if frequency == freq_khz:
                    continue
                state.set_view(freq_khz=frequency)
                display_freq = frequency
                candidate_freq = frequency
                anim_start = 0.0
                inertia_velocity_khz_s = 0.0
                remember_current_view()
                continue

            if kind == "dial" and rc28_dial_mode == "VOLUME":
                # Two percent per detent gives the 24-detent wheel a useful
                # half-range sweep without forcing the operator to make
                # tiny, fussy turns for normal listening adjustments.
                current_volume = audio_volume if audio_volume is not None else 0.5
                apply_main_volume(clamp(current_volume + int(value) * 0.02, 0.0, 1.0))
                rc28_mode_osd_until = time.monotonic() + 1.7
                wake_controls()
                continue

            if kind == "dial" and rc28_dial_mode in ("WIDTH", "SHIFT"):
                _mode, low_cut, high_cut, _radio_generation = state.radio_snapshot()
                current_width = max(FILTER_SNAP_HZ, high_cut - low_cut)
                center = filter_center_hz(low_cut, high_cut)
                detents = int(value)
                if rc28_dial_mode == "WIDTH":
                    # One 24-detent revolution changes a normal 2.4 kHz
                    # voice passband by 2.4 kHz: quick enough to explore,
                    # but still precise for CW.
                    width = clamp(
                        current_width + detents * FILTER_FINE_WIDTH_STEP_HZ,
                        FILTER_SNAP_HZ,
                        FILTER_LIMIT_HZ * 2,
                    )
                    half_width = width / 2.0
                    center = clamp(center, -FILTER_LIMIT_HZ + half_width, FILTER_LIMIT_HZ - half_width)
                    state.set_filter(low_cut=center - half_width, high_cut=center + half_width)
                else:
                    # Shift preserves the exact width and moves both edges
                    # together.  The 50 Hz snap is deliberate for narrow
                    # digital/CW filters and remains comfortable on SSB.
                    half_width = current_width / 2.0
                    center = clamp(
                        center + detents * FILTER_SNAP_HZ,
                        -FILTER_LIMIT_HZ + half_width,
                        FILTER_LIMIT_HZ - half_width,
                    )
                    state.set_filter(low_cut=center - half_width, high_cut=center + half_width)
                rc28_mode_osd_until = time.monotonic() + 1.7
                wake_controls()
                continue

            if kind == "dial":
                # Eight physical detents per zoom step, limited to 10 Hz,
                # makes Zoom deliberate even when the wheel is spun quickly.
                value = int(value)
                if rc28_zoom_detents and value and (rc28_zoom_detents > 0) != (value > 0):
                    # Do not make the operator unwind old travel before a
                    # reverse turn takes effect.
                    rc28_zoom_detents = value
                else:
                    rc28_zoom_detents = clamp(rc28_zoom_detents + value, -15, 15)
                now_rc28 = time.monotonic()
                if abs(rc28_zoom_detents) >= 8 and now_rc28 - rc28_zoom_last_at >= 0.10:
                    zoom_delta = 1 if rc28_zoom_detents > 0 else -1
                    _server, _freq_khz, current_zoom, _smeter, _generation, _server_generation = state.snapshot()
                    minimum_zoom = rtl_lab.minimum_zoom() if (state.external_waterfall_snapshot() or rtl_lab.is_running()) else 0
                    if (zoom_delta > 0 and current_zoom >= args.max_zoom) or (zoom_delta < 0 and current_zoom <= minimum_zoom):
                        # At an endpoint there is no useful residual travel to
                        # replay when the dial turns back the other way.
                        rc28_zoom_detents = 0
                    else:
                        rc28_zoom_detents -= zoom_delta * 8
                        change_zoom(zoom_delta, animation_duration=0.08)
                    rc28_zoom_last_at = now_rc28
                continue
            if value == "f1_zoom_out":
                change_zoom(-1)
            elif value == "f2_zoom_in":
                change_zoom(1)

    def set_test_frequency(freq_khz):
        """Publish a fresh desired tune; workers consume state, not a queue."""
        nonlocal display_freq, candidate_freq, anim_start, inertia_velocity_khz_s
        frequency = clamp_active_frequency(freq_khz)
        state.set_view(freq_khz=frequency)
        display_freq = frequency
        candidate_freq = frequency
        anim_start = 0.0
        inertia_velocity_khz_s = 0.0

    def start_retune_sweep():
        nonlocal retune_sweep, display_freq, candidate_freq, anim_start, inertia_velocity_khz_s
        _server, freq_khz, _zoom, _smeter, _generation, _server_generation = state.snapshot()
        retune_sweep = RetuneSweep(freq_khz, retune_pattern_index, time.monotonic())
        display_freq = freq_khz
        candidate_freq = freq_khz
        anim_start = 0.0
        inertia_velocity_khz_s = 0.0
        wake_controls()
        print(f"gl test start {retune_sweep.name} {retune_sweep.command_count} at {freq_khz:.3f} kHz", flush=True)

    def stop_retune_sweep(reason):
        nonlocal retune_sweep
        if retune_sweep is None:
            return
        start_khz = retune_sweep.start_khz
        retune_sweep = None
        set_test_frequency(start_khz)
        remember_current_view()
        print(f"gl test {reason}; restored {start_khz:.3f} kHz", flush=True)

    def advance_retune_sweep(now):
        nonlocal retune_sweep
        if retune_sweep is None:
            return
        step = retune_sweep.advance(now)
        if step is None:
            return
        frequency, done = step
        set_test_frequency(frequency)
        if done:
            finished = retune_sweep
            retune_sweep = None
            remember_current_view()
            print(f"gl test complete {finished.name}; restored {frequency:.3f} kHz", flush=True)

    def open_dj_tune():
        nonlocal dj_tune_open, dj_origin_khz, dj_current_khz, dj_drag_remainder_hz
        _server, frequency, _zoom, _smeter, _generation, _server_generation = state.snapshot()
        dj_tune_open = True
        dj_origin_khz = frequency
        dj_current_khz = frequency
        dj_drag_remainder_hz = 0.0
        wake_controls()

    def wspr_receiver_choices():
        """Pin the LAN Kiwi, then offer the current radio and live directory."""
        active_server, _freq, _zoom, _smeter, _generation, _server_generation = state.snapshot()
        ordered = [LOCAL_KIWI_STATION]
        seen = {LOCAL_KIWI_SERVER.rstrip("/")}
        for station in all_stations:
            _name, _location, candidate_server, _used, _total = station_fields(station)
            if candidate_server.rstrip("/") == active_server.rstrip("/") and candidate_server.rstrip("/") not in seen:
                ordered.append(station)
                seen.add(candidate_server.rstrip("/"))
                break
        if active_server.rstrip("/") not in seen:
            ordered.append(("CURRENT RECEIVER", active_server, active_server))
            seen.add(active_server.rstrip("/"))
        for station in all_stations:
            _name, _location, candidate_server, _used, _total = station_fields(station)
            normalized_server = candidate_server.rstrip("/")
            if normalized_server and normalized_server not in seen:
                ordered.append(station)
                seen.add(normalized_server)
        return ordered

    def open_wspr_add_sheet():
        """Seed WSPR on the local Kiwi while retaining the active band context."""
        nonlocal wspr_add_open, wspr_add_band, wspr_add_server, wspr_add_station_page
        active_server, active_frequency, _zoom, _smeter, _generation, _server_generation = state.snapshot()
        wspr_add_open = True
        wspr_add_band = nearest_wspr_band(active_frequency)
        wspr_add_server = LOCAL_KIWI_SERVER
        choices = wspr_receiver_choices()
        active_index = next((index for index, station in enumerate(choices) if station_fields(station)[2].rstrip("/") == LOCAL_KIWI_SERVER.rstrip("/")), 0)
        wspr_add_station_page = active_index // 3
        wake_controls()

    def connect_to_station(station):
        """Use one path for normal list taps and the Home local-receiver key."""
        nonlocal station_pending_server, station_pending_started_at, station_connected_at, zoom_osd_until
        name, _location, target_server, _used, _total = station_fields(station)
        _server, frequency, zoom, _generation, _server_generation = state.set_server(target_server)
        write_remembered_view(save_current_frequency=True, force=True)
        drain_queue(line_queue)
        wf_texture.clear()
        animate_to(frequency, kiwi.zoom_to_span_khz(zoom), 0.20)
        station_pending_server = target_server
        station_pending_started_at = time.monotonic()
        station_connected_at = 0.0
        zoom_osd_until = time.monotonic() + args.zoom_osd_seconds
        print(f"gl station {name}: {target_server}", flush=True)

    def toggle_openwebrx_test():
        """Enter/leave the fixed OpenWebRX smoke receiver without persistence."""
        nonlocal openwebrx_test_restore, radio_mode, manual_radio_mode
        nonlocal filter_custom_width, digital_mode, display_freq, display_span
        nonlocal candidate_freq, anim_start, inertia_velocity_khz_s
        if openwebrx_test_restore is None:
            prior_server, prior_frequency, prior_zoom, _smeter, _generation, _server_generation = state.snapshot()
            prior_mode, _low_cut, _high_cut, _radio_generation = state.radio_snapshot()
            openwebrx_test_restore = {
                "server": prior_server,
                "frequency": prior_frequency,
                "zoom": prior_zoom,
                "mode": prior_mode.upper(),
                "manual_mode": manual_radio_mode,
            }
            target_server = OPENWEBRX_TEST_SERVER
            target_frequency = OPENWEBRX_TEST_FREQUENCY_KHZ
            target_zoom = OPENWEBRX_TEST_ZOOM
            target_mode = OPENWEBRX_TEST_MODE
            manual_radio_mode = True
            digital_mode = "DIG"
            print("gl OpenWebRX test started", flush=True)
        else:
            restore = openwebrx_test_restore
            openwebrx_test_restore = None
            target_server = restore["server"]
            target_frequency = restore["frequency"]
            target_zoom = restore["zoom"]
            target_mode = restore["mode"]
            manual_radio_mode = bool(restore["manual_mode"])
            print(f"gl OpenWebRX test restored {target_server}", flush=True)
        _server, _frequency, _zoom, _generation, _server_generation = state.set_server(
            target_server, zoom=target_zoom,
        )
        radio_mode = target_mode
        state.set_radio_mode(radio_mode)
        filter_custom_width = False
        state.set_view(freq_khz=target_frequency, zoom=target_zoom)
        display_freq = target_frequency
        display_span = kiwi.zoom_to_span_khz(target_zoom)
        candidate_freq = target_frequency
        anim_start = 0.0
        inertia_velocity_khz_s = 0.0
        drain_queue(line_queue)
        wf_texture.clear()

    def refresh_wspr_waterfalls():
        """Keep active WSPR cards current even while their workspace is hidden."""
        wspr_monitor.sync(wspr_tiles)
        active_texture_keys = {str(tile.get("id")) for tile in wspr_tiles}
        for key in tuple(wspr_mini_textures):
            if key not in active_texture_keys:
                wspr_mini_textures.pop(key).close()
        for key, session in wspr_monitor.sessions.items():
            texture = wspr_mini_textures.get(key)
            if texture is None:
                texture = MiniWaterfallTexture()
                wspr_mini_textures[key] = texture
            session.drain_rows(texture)

    def activate_navigation_item(index, items=MENU_ITEMS):
        """Open a Home tool directly from the persistent 1280 desktop rail."""
        nonlocal menu_open, picker_open, picker_map_open, picker_map_garden_mode, radio_setup_open, display_setup_open, filter_drawer_open, settings_menu_open, digital_menu_open, receiver_home_panel_open, fan_curve_panel_open, network_panel_open, network_password_open, network_selected_ssid, network_password_value, network_password_placeholder_visible, network_password_revealed, network_keyboard_caps, network_notice, network_next_refresh
        nonlocal audio_panel_open, asr_panel_open, asr_moon_language_open, audio_volume, tests_panel_open, font_lab_open, font_lab_page, compact_font_review_open, rtl_lab_open, dual_vfo_open, dual_vfo_has_session, dual_vfo_active, dual_vfo_mix, dual_vfo_sources, dual_vfo_profiles, dual_vfo_picker_open, dual_vfo_picker_target, dual_vfo_picker_page, dual_vfo_mode_open, dual_vfo_mode_target, wspr_panel_open, wspr_identity_open, wspr_add_open, wspr_decoder_settings_open, dj_tune_open, cpu_utilization_graph_open
        nonlocal wspr_expanded_log_open, wspr_expanded_log_id, wspr_expanded_log_scroll
        nonlocal wspr_expanded_waterfall_open, wspr_expanded_waterfall_id, wspr_expanded_waterfall_scroll
        nonlocal wspr_expanded_graph_open, wspr_expanded_graph_id, wspr_expanded_graph_page
        nonlocal wspr_tile_band_open
        nonlocal filter_panel_open, station_scroll, station_query, station_sort, station_route_filter, favorite_servers
        nonlocal stations, search_open, radio_family_open, station_pending_server, station_connected_at
        kind, label = items[index]
        wake_controls()
        menu_open = False
        # Navigating away from Dual must release its extra SND/W/F pair before
        # another receiver-facing page has a chance to open sockets.
        if dual_vfo_open and kind != "dual":
            stop_dual_vfo_clients()
        dual_vfo_open = False
