            picker_open = True
            radio_setup_open = display_setup_open = filter_drawer_open = receiver_home_panel_open = fan_curve_panel_open = audio_panel_open = asr_panel_open = False
            tests_panel_open = dj_tune_open = filter_panel_open = False
