                                    applied_pitch = pitch_delta * smoothing
                                    picker_map_yaw = (picker_map_yaw + applied_yaw + math.pi) % math.tau - math.pi
                                    picker_map_pitch = clamp(
                                        picker_map_pitch + applied_pitch,
                                        math.radians(-80), math.radians(80),
                                    )
